		for j := 1; j <= len(br); j++ {
			cost := 0
			if ar[i-1] != br[j-1] {
				cost = 1
			}
			cur[j] = min3(prev[j]+1, cur[j-1]+1, prev[j-1]+cost)
		}
		copy(prev, cur)
	}
	return prev[len(br)]
}

func min3(a, b, c int) int {
	if a < b {
		if a < c {
			return a
		}
		return c
	}
	if b < c {
		return b
	}
	return c
}

func formatFlagName(name string) string {
	if len([]rune(name)) == 1 {
		return "-" + name
	}
	return "--" + name
}

func suggestFlag(name string, candidates []string) string {
	best := ""
	bestDist := 0
	for _, cand := range candidates {
		d := levenshtein(name, cand)
		if best == "" || d < bestDist {
			best = cand
			bestDist = d
		}
	}
	if best == "" {
		return ""
	}
	if bestDist <= 4 && bestDist < len([]rune(name)) {
		return best
	}
	return ""
}

var unknownFlagRE = regexp.MustCompile(`^flag provided but not defined: -(.+)$`)

func transformFlagError(err error, candidates []string) error {
	m := unknownFlagRE.FindStringSubmatch(err.Error())
	if m == nil {
		return err
	}
	name := m[1]
	msg := "unknown flag: " + formatFlagName(name)
	if suggestion := suggestFlag(name, candidates); suggestion != "" {
		msg += "\n\nDid you mean " + formatFlagName(suggestion) + " instead?"
	}
	return &cliError{msg: msg}
}

func parseFlags(args []string, opts *cliOptions) ([]string, error) {
	fs := flag.NewFlagSet("", flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	fs.Usage = func() {}

	fs.BoolVar(&opts.version, "v", false, "")
	fs.BoolVar(&opts.version, "version", false, "")
	fs.Var(&opts.input, "input", "")
	fs.Var(&opts.output, "output", "")
	fs.BoolVar(&opts.overwrite, "output-overwrite", false, "")
	fs.StringVar(&opts.domain, "domain", "", "")
	fs.Var(&opts.exclude, "exclude-selector", "")
	fs.Var(&opts.include, "include-selector", "")
	fs.StringVar(&opts.strongDelim, "opt-strong-delimiter", "", "")
	fs.StringVar(&opts.tablePadding, "opt-table-cell-padding-behavior", "", "")
	fs.BoolVar(&opts.tableHeaderProm, "opt-table-header-promotion", false, "")
	fs.StringVar(&opts.tableNewline, "opt-table-newline-behavior", "", "")
	fs.BoolVar(&opts.tablePresentation, "opt-table-presentation-tables", false, "")
	fs.BoolVar(&opts.tableSkipEmpty, "opt-table-skip-empty-rows", false, "")
	fs.StringVar(&opts.tableSpan, "opt-table-span-cell-behavior", "", "")
	fs.BoolVar(&opts.pluginStrikethrough, "plugin-strikethrough", false, "")
	fs.BoolVar(&opts.pluginTable, "plugin-table", false, "")

	var candidates []string
	fs.VisitAll(func(f *flag.Flag) { candidates = append(candidates, f.Name) })

	err := fs.Parse(args)
	if err != nil {
		if errors.Is(err, flag.ErrHelp) {
			return nil, flag.ErrHelp
		}
		return nil, transformFlagError(err, candidates)
	}
	return fs.Args(), nil
}

func checkTableRequirements(opts *cliOptions) error {
	if opts.pluginTable {
		return nil
	}
	type check struct {
		name    string
		present bool
	}
	checks := []check{
		{"--opt-table-skip-empty-rows", opts.tableSkipEmpty},
		{"--opt-table-header-promotion", opts.tableHeaderProm},
		{"--opt-table-span-cell-behavior", opts.tableSpan != ""},
		{"--opt-table-presentation-tables", opts.tablePresentation},
		{"--opt-table-newline-behavior", opts.tableNewline != ""},
		{"--opt-table-cell-padding-behavior", opts.tablePadding != ""},
	}
	for _, c := range checks {
		if c.present {
			return newCLIError("%s requires --plugin-table to be enabled", c.name)
		}
	}
	return nil
}

func newConverterFromOptions(opts *cliOptions) (*converter, error) {
	conv := newConverter()
	conv.domain = opts.domain
	conv.pluginStrikethrough = opts.pluginStrikethrough
	conv.pluginTable = opts.pluginTable
	conv.includeSelectors = opts.include.selectors
	conv.excludeSelectors = opts.exclude.selectors
	if opts.pluginTable {
		if opts.tableSpan != "" {
			switch opts.tableSpan {
			case "empty", "mirror":
				conv.tableSpan = opts.tableSpan
			default:
				return nil, newCLIError("error while initializing \"table\" plugin: unknown value %q for span cell behavior", opts.tableSpan)
			}
		}
		if opts.tableNewline != "" {
			switch opts.tableNewline {
			case "skip", "preserve":
				conv.tableNewline = opts.tableNewline
			default:
				return nil, newCLIError("error while initializing \"table\" plugin: unknown value %q for newline behavior", opts.tableNewline)
			}
		}
		if opts.tablePadding != "" {
			switch opts.tablePadding {
			case "aligned", "minimal", "none":
				conv.tablePadding = opts.tablePadding
			default:
				return nil, newCLIError("error while initializing \"table\" plugin: unknown value %q for cell padding behavior", opts.tablePadding)
			}
		}
		conv.tableHeaderPromotion = opts.tableHeaderProm
		conv.tablePresentation = opts.tablePresentation
		conv.tableSkipEmpty = opts.tableSkipEmpty
	}
	if opts.strongDelim != "" {
		if opts.strongDelim != "**" && opts.strongDelim != "__" {
			return nil, newCLIError("invalid value for --opt-strong-delimiter=%q must be exactly 2 characters of \"**\" or \"__\"", opts.strongDelim)
		}
		conv.strongDelimiter = opts.strongDelim
	}
	return conv, nil
}

// strconv is retained for flag error parity in some Go versions; keep a
// tiny reference so this file documents the stdlib boolean grammar.
var _ = strconv.ParseBool

func run(args []string) error {
	var opts cliOptions
	rest, err := parseFlags(args, &opts)
	if err != nil {
		if errors.Is(err, flag.ErrHelp) {
			fmt.Fprint(os.Stdout, helpText)
			return nil
		}
		return err
	}
	if len(rest) > 0 {
		return withCLIUsage("unknown arguments: " + strings.Join(rest, " "))
	}
	if opts.version {
		fmt.Fprint(os.Stdout, versionText)
		return nil
	}
	if err := checkTableRequirements(&opts); err != nil {
		return err
	}
	jobs, toStdout, err := resolveIO(&opts)
	if err != nil {
		return err
	}
	var conv *converter
	for _, job := range jobs {
		var input []byte
		if job.stdin {
			input, err = io.ReadAll(os.Stdin)
			if err != nil {
				return err
			}
		} else {
			input, err = os.ReadFile(job.input)
			if err != nil {
				return err
			}
		}
		if conv == nil {
			conv, err = newConverterFromOptions(&opts)
			if err != nil {
				return err
			}
		}
		markdown, err := conv.convert(input)
		if err != nil {
			return err
		}
		if toStdout {
			fmt.Fprintln(os.Stdout, markdown)
		} else {
			if err := os.WriteFile(job.output, []byte(markdown), 0644); err != nil {
				return fmt.Errorf("error while writing the file: %w", err)
			}
		}
	}
	return nil
}

func main() {
	if err := run(os.Args[1:]); err != nil {
		fmt.Fprintf(os.Stderr, "\nerror: %s\n\n", err.Error())
		os.Exit(1)
	}
}
GO
