func resolveIO(opts *cliOptions) ([]ioJob, bool, error) {
	var inputs []string
	isStdin := false
	if opts.input.set {
		inputStr := opts.input.value
		if info, err := os.Stat(inputStr); err == nil && info.IsDir() {
			return nil, false, withGlobUsage("input path \"" + inputStr + "\" is a directory, not a file")
		}
