		inputs = []string{""}
	}

	outputSet := opts.output.set
	outputStr := opts.output.value

	if len(inputs) > 1 {
		if !outputSet {
			return nil, false, withGlobUsage("when processing multiple input files --output needs to be a directory")
		}
		if !strings.HasSuffix(outputStr, "/") {
			return nil, false, newCLIError("when processing multiple input files, --output %q must end with %q to indicate a directory", outputStr, outputStr+"/")
		}
	}

	if !outputSet {
		// stdout; exactly one job reaches this point.
		return []ioJob{{input: inputs[0], stdin: isStdin}}, true, nil
	}

	isDirOutput := strings.HasSuffix(outputStr, "/")
	var outputs []string
	if isDirOutput {
		if err := os.MkdirAll(outputStr, 0755); err != nil {
			return nil, false, err
		}
		used := make(map[string]bool)
		patternBase := ""
		if opts.input.set {
			patternBase = splitPatternBase(opts.input.value)
		}
		for _, in := range inputs {
			var name string
			if isStdin {
				name = "output.md"
			} else {
				name = outputNameFor(in)
				if used[name] {
					rel := in
					if patternBase != "" {
						if r, err := filepath.Rel(patternBase, in); err == nil {
							rel = r
						}
					}
					sum := sha256.Sum256([]byte(filepath.ToSlash(rel)))
					hash := hex.EncodeToString(sum[:])[:10]
					base := filepath.Base(in)
					ext := filepath.Ext(base)
					stem := strings.TrimSuffix(base, ext)
					name = stem + "." + hash + ".md"
				}
			}
			used[name] = true
			outputs = append(outputs, filepath.Join(outputStr, name))
		}
	} else {
		if info, err := os.Stat(outputStr); err == nil && info.IsDir() {
			return nil, false, &cliError{msg: "path \"" + outputStr + "\" exists and is a directory, did you mean \"" + outputStr + "/\"?\n\nThe --output must end with \"/\" to indicate a directory"}
		}
		parent := filepath.Dir(outputStr)
		if err := os.MkdirAll(parent, 0755); err != nil {
			return nil, false, err
		}
		outputs = []string{outputStr}
	}

	if !opts.overwrite {
		for _, out := range outputs {
			if _, err := os.Stat(out); err == nil {
				return nil, false, newCLIError("output path %q already exists. Use --output-overwrite to replace existing files", outputStr)
			}
		}
	}

	jobs := make([]ioJob, 0, len(inputs))
	for i, in := range inputs {
		jobs = append(jobs, ioJob{input: in, output: outputs[i], stdin: isStdin})
	}
	return jobs, false, nil
}
