package main

import (
	"os"
	"path/filepath"
	"sort"
	"strings"
	"unicode/utf8"
)

// fileGlob implements the subset of the doublestar-style glob language the
// CLI exposes: *, ?, character classes, {a,b} alternatives and ** as a
// complete path segment. Validation failures deliberately use the same
// string as filepath.ErrBadPattern.

func badPattern() error { return filepath.ErrBadPattern }

func isMetaByte(s string) int {
	inClass := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\\' {
			i++
			continue
		}
		if inClass {
			if c == ']' {
				inClass = false
			}
			continue
		}
		switch c {
		case '[':
			inClass = true
		case '*', '?', '{':
			return i
		}
	}
	return -1
}

func splitPatternBase(pattern string) string {
	clean := filepath.Clean(pattern)
	idx := isMetaByte(clean)
	if idx < 0 {
		return clean
	}
	slash := strings.LastIndex(clean[:idx], "/")
	if slash < 0 {
		return "."
	}
	if slash == 0 {
		return "/"
	}
	return clean[:slash]
}

// expandBraces returns all brace expansions. It validates unmatched braces.
func expandBraces(pattern string) ([]string, error) {
	// Find the first unescaped, non-class brace.
	start := -1
	inClass := false
	for i := 0; i < len(pattern); i++ {
		c := pattern[i]
		if c == '\\' {
			if i+1 >= len(pattern) {
				return nil, badPattern()
			}
			i++
			continue
		}
		if inClass {
			if c == ']' {
				inClass = false
			}
			continue
		}
		if c == '[' {
			inClass = true
			continue
		}
		if c == '}' {
			return nil, badPattern()
		}
		if c == '{' {
			start = i
			break
		}
	}
	if start < 0 {
		return []string{pattern}, nil
	}
	depth := 0
	end := -1
	inClass = false
	for i := start; i < len(pattern); i++ {
		c := pattern[i]
		if c == '\\' {
			i++
			continue
		}
		if inClass {
			if c == ']' {
				inClass = false
			}
			continue
		}
		switch c {
		case '[':
			inClass = true
		case '{':
			depth++
		case '}':
			depth--
			if depth == 0 {
				end = i
			}
		}
		if end >= 0 {
			break
		}
	}
	if end < 0 {
		return nil, badPattern()
	}
	inside := pattern[start+1 : end]
	var alts []string
	depth = 0
	inClass = false
	last := 0
	for i := 0; i < len(inside); i++ {
		c := inside[i]
		if c == '\\' {
			i++
			continue
		}
		if inClass {
			if c == ']' {
				inClass = false
			}
			continue
		}
		switch c {
		case '[':
			inClass = true
		case '{':
			depth++
		case '}':
			depth--
		case ',':
			if depth == 0 {
				alts = append(alts, inside[last:i])
				last = i + 1
			}
		}
	}
	alts = append(alts, inside[last:])
	var out []string
	for _, alt := range alts {
		expanded, err := expandBraces(pattern[:start] + alt + pattern[end+1:])
		if err != nil {
			return nil, err
		}
		out = append(out, expanded...)
	}
	return out, nil
}

type classRange struct{ lo, hi rune }

type segToken struct {
	kind    byte // 'l' literal, '*', '?', 'c' class
	lit     rune
	neg     bool
	ranges  []classRange
	literal map[rune]bool
}

func parseEscapeAt(s string, i int) (rune, int, error) {
	// s[i] is a backslash.
	if i+1 >= len(s) {
		return 0, 0, badPattern()
	}
	r, size := utf8.DecodeRuneInString(s[i+1:])
	if r == '\n' {
		return 0, 0, badPattern()
	}
	return r, 1 + size, nil
}

func parseSegmentTokens(seg string) ([]segToken, error) {
	var toks []segToken
	i := 0
	for i < len(seg) {
		c := seg[i]
		switch c {
		case '*':
			toks = append(toks, segToken{kind: '*'})
			i++
		case '?':
			toks = append(toks, segToken{kind: '?'})
			i++
		case '\\':
			r, size, err := parseEscapeAt(seg, i)
			if err != nil {
				return nil, err
			}
			toks = append(toks, segToken{kind: 'l', lit: r})
			i += size
		case '[':
			tok := segToken{kind: 'c', literal: make(map[rune]bool)}
			i++
			if i < len(seg) && (seg[i] == '!' || seg[i] == '^') {
				tok.neg = true
				i++
			}
			if i >= len(seg) || seg[i] == ']' {
				return nil, badPattern()
			}
			closed := false
			for i < len(seg) {
				if seg[i] == ']' {
					closed = true
					i++
					break
				}
				var lo rune
				if seg[i] == '\\' {
					r, size, err := parseEscapeAt(seg, i)
					if err != nil {
						return nil, err
					}
					lo = r
					i += size
				} else {
					r, size := utf8.DecodeRuneInString(seg[i:])
					lo = r
					i += size
				}
				// A '-' forms a range only when followed by a real
				// character other than the closing bracket.
				if i < len(seg) && seg[i] == '-' && i+1 < len(seg) && seg[i+1] != ']' {
					i++
					var hi rune
					if seg[i] == '\\' {
						r, size, err := parseEscapeAt(seg, i)
						if err != nil {
							return nil, err
						}
						hi = r
						i += size
					} else {
						r, size := utf8.DecodeRuneInString(seg[i:])
						hi = r
						i += size
					}
					if lo > hi {
						// Observed behaviour: a reversed range
						// matches only its first endpoint.
						tok.literal[lo] = true
					} else {
						tok.ranges = append(tok.ranges, classRange{lo, hi})
					}
				} else {
					tok.literal[lo] = true
				}
			}
			if !closed {
				return nil, badPattern()
			}
			toks = append(toks, tok)
		default:
			r, size := utf8.DecodeRuneInString(seg[i:])
			toks = append(toks, segToken{kind: 'l', lit: r})
			i += size
		}
	}
	return toks, nil
}

func tokenMatches(t segToken, r rune) bool {
	switch t.kind {
	case 'l':
		return r == t.lit
	case '?':
		return r != '/'
	case 'c':
		ok := t.literal[r]
		if !ok {
			for _, rg := range t.ranges {
				if r >= rg.lo && r <= rg.hi {
					ok = true
					break
				}
			}
		}
		if t.neg {
			return !ok
		}
		return ok
	}
	return false
}

func matchSegment(pattern, name string) (bool, error) {
	toks, err := parseSegmentTokens(pattern)
	if err != nil {
		return false, err
	}
	nr := []rune(name)
	// DP over tokens and name positions.
	type key struct{ t, n int }
	memo := make(map[key]bool)
	seen := make(map[key]bool)
	var rec func(t, n int) bool
	rec = func(t, n int) bool {
		k := key{t, n}
		if seen[k] {
			return memo[k]
		}
		seen[k] = true
		var res bool
		defer func() { memo[k] = res }()
		if t == len(toks) {
			res = n == len(nr)
			return res
		}
		if toks[t].kind == '*' {
			// Collapse consecutive stars semantically.
			res = rec(t+1, n)
			for i := n; !res && i < len(nr); i++ {
				res = rec(t+1, i+1)
			}
			return res
		}
		if n >= len(nr) {
			res = false
			return res
		}
		res = tokenMatches(toks[t], nr[n]) && rec(t+1, n+1)
		return res
	}
	return rec(0, 0), nil
}

func validateExpandedPattern(pattern string) error {
	for _, seg := range strings.Split(pattern, "/") {
		if _, err := parseSegmentTokens(seg); err != nil {
			return err
		}
	}
	return nil
}

func matchPath(pattern, name string) bool {
	psegs := strings.Split(pattern, "/")
	nsegs := strings.Split(name, "/")
	type key struct{ p, n int }
	memo := make(map[key]bool)
	seen := make(map[key]bool)
	var rec func(p, n int) bool
	rec = func(p, n int) bool {
		k := key{p, n}
		if seen[k] {
			return memo[k]
		}
		seen[k] = true
		var res bool
		defer func() { memo[k] = res }()
		if p == len(psegs) {
			res = n == len(nsegs)
			return res
		}
		if psegs[p] == "**" {
			res = rec(p+1, n)
			for i := n; !res && i < len(nsegs); i++ {
				res = rec(p, i+1)
			}
			return res
		}
		if n >= len(nsegs) {
			res = false
			return res
		}
		ok, err := matchSegment(psegs[p], nsegs[n])
		res = err == nil && ok && rec(p+1, n+1)
		return res
	}
	return rec(0, 0)
}

func fileGlob(pattern string) ([]string, error) {
	expanded, err := expandBraces(pattern)
	if err != nil {
		return nil, err
	}
	var patterns []string
	for _, p := range expanded {
		clean := filepath.Clean(p)
		// filepath.Clean turns an empty pattern into "."; the
		// cleaned slash form is what we match candidates against.
		clean = filepath.ToSlash(clean)
		if err := validateExpandedPattern(clean); err != nil {
			return nil, err
		}
		patterns = append(patterns, clean)
	}

	base := splitPatternBase(pattern)
	// How deep do we need to walk from base?
	unlimited := false
	maxExtra := 0
	for _, p := range patterns {
		rel := p
		b := splitPatternBase(p)
		if b != "." && b != "/" {
			if r, err := filepath.Rel(b, p); err == nil {
				rel = filepath.ToSlash(r)
			}
		} else if b == "/" {
			rel = strings.TrimPrefix(p, "/")
		} else if b == "." {
			rel = p
		}
		segs := strings.Split(rel, "/")
		for _, s := range segs {
			if s == "**" {
				unlimited = true
			}
		}
		if len(segs) > maxExtra {
			maxExtra = len(segs)
		}
	}

	var matches []string
	seenMatch := make(map[string]bool)

	var walk func(dirOS, dirDisp string, depth int) error
	walk = func(dirOS, dirDisp string, depth int) error {
		entries, err := os.ReadDir(dirOS)
		if err != nil {
			if depth == 0 {
				return nil
			}
			return err
		}
		sort.Slice(entries, func(i, j int) bool { return entries[i].Name() < entries[j].Name() })
		for _, e := range entries {
			disp := e.Name()
			if dirDisp != "" {
				disp = dirDisp + "/" + e.Name()
			}
			disp = filepath.ToSlash(filepath.Clean(disp))
			childOS := filepath.Join(dirOS, e.Name())
			if e.IsDir() {
				if unlimited || depth+1 < maxExtra {
					if err := walk(childOS, disp, depth+1); err != nil {
						return err
					}
				}
				continue
			}
			for _, p := range patterns {
				if matchPath(p, disp) {
					if !seenMatch[disp] {
						seenMatch[disp] = true
						matches = append(matches, disp)
					}
					break
				}
			}
		}
		return nil
	}

	baseDisp := ""
	if base != "." {
		baseDisp = filepath.ToSlash(base)
	}
	if err := walk(base, baseDisp, 0); err != nil {
		return nil, err
	}
	return matches, nil
}
