		b.WriteRune(p.next())
	} else {
		return "", fmt.Errorf("expected identifier, found %s instead", foundWhat(p))
	}
	for !p.eof() {
		r, _ := p.peek()
		if r == '\\' {
			p.next()
			er, err := p.parseEscape()
			if err != nil {
				return "", err
			}
			b.WriteRune(er)
		} else if isNameChar(r) {
			b.WriteRune(p.next())
		} else {
			break
		}
	}
	return b.String(), nil
}

func (p *selParser) parseName() (string, error) {
	var b strings.Builder
	for !p.eof() {
		r, _ := p.peek()
		if r == '\\' {
			p.next()
			er, err := p.parseEscape()
			if err != nil {
				return "", err
			}
			b.WriteRune(er)
		} else if isNameChar(r) {
			b.WriteRune(p.next())
		} else {
			break
		}
	}
	if b.Len() == 0 {
		return "", fmt.Errorf("expected name, found %s instead", foundWhat(p))
	}
	return b.String(), nil
}

func (p *selParser) parseString() (string, error) {
	quote := p.next() // ' or "
	var b strings.Builder
	for !p.eof() {
		r := p.next()
		if r == quote {
			return b.String(), nil
		}
		if r == '\\' {
			if p.eof() {
				return "", fmt.Errorf("EOF in string")
			}
			// CSS string escapes share identifier escape rules.
			p.i-- // step back over the backslash rune (ASCII)
			p.next()
			er, err := p.parseEscape()
			if err != nil {
				return "", fmt.Errorf("EOF in string")
			}
			b.WriteRune(er)
			continue
		}
		if r == '\n' {
			return "", fmt.Errorf("EOF in string")
		}
		b.WriteRune(r)
	}
	return "", fmt.Errorf("EOF in string")
}

func (p *selParser) parseAttribute() (func(*html.Node) bool, error) {
	p.next() // [
	p.skipSpaces()
	key, err := p.parseIdentifier()
