package main

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"

	"golang.org/x/net/html"
)

// Selector is a compiled CSS selector (possibly a group).
type Selector interface {
	Match(*html.Node) bool
}

type selectorGroup []Selector

func (g selectorGroup) Match(n *html.Node) bool {
	for _, s := range g {
		if s.Match(n) {
			return true
		}
	}
	return false
}

type compoundSelector struct {
	tag string // "" for universal
	conds []func(*html.Node) bool
}

func (c *compoundSelector) Match(n *html.Node) bool {
	if n.Type != html.ElementNode {
		return false
	}
	if c.tag != "" && strings.ToLower(n.Data) != c.tag {
		return false
	}
	for _, f := range c.conds {
		if !f(n) {
			return false
		}
	}
	return true
}

type relativeSelector struct {
	combinator byte // ' ' descendant, '>', '+', '~'
	first      Selector
	second     Selector
}

func (r *relativeSelector) Match(n *html.Node) bool {
	if !r.second.Match(n) {
		return false
	}
	switch r.combinator {
	case '>':
		p := n.Parent
		return p != nil && p.Type == html.ElementNode && r.first.Match(p)
	case '+':
		for s := n.PrevSibling; s != nil; s = s.PrevSibling {
			if s.Type == html.ElementNode {
				return r.first.Match(s)
			}
		}
		return false
	case '~':
		for s := n.PrevSibling; s != nil; s = s.PrevSibling {
			if s.Type == html.ElementNode && r.first.Match(s) {
				return true
			}
		}
		return false
	default: // descendant
		for p := n.Parent; p != nil; p = p.Parent {
			if p.Type == html.ElementNode && r.first.Match(p) {
				return true
			}
		}
		return false
	}
}

// ---------- node helpers ----------

func nodeAttr(n *html.Node, key string) (string, bool) {
	for _, a := range n.Attr {
		if a.Key == key {
			return a.Val, true
		}
	}
	return "", false
}

func elementSiblings(n *html.Node) []*html.Node {
	if n.Parent == nil {
		return []*html.Node{n}
	}
	var out []*html.Node
	for c := n.Parent.FirstChild; c != nil; c = c.NextSibling {
		if c.Type == html.ElementNode {
			out = append(out, c)
		}
	}
	return out
}

func textContent(n *html.Node) string {
	var b strings.Builder
	var rec func(*html.Node)
	rec = func(x *html.Node) {
		if x.Type == html.TextNode {
			b.WriteString(x.Data)
			return
		}
		for c := x.FirstChild; c != nil; c = c.NextSibling {
			rec(c)
		}
	}
	rec(n)
	return b.String()
}

func ownTextContent(n *html.Node) string {
	var b strings.Builder
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		if c.Type == html.TextNode {
			b.WriteString(c.Data)
		}
	}
	return b.String()
}

func nthMatches(a, b, index int) bool {
	// index is 1-based.
	if a == 0 {
		return index == b
	}
	diff := index - b
	if diff%a != 0 {
		return false
	}
	return diff/a >= 0
}

func isFormControl(n *html.Node) bool {
	switch strings.ToLower(n.Data) {
	case "button", "input", "select", "textarea", "optgroup", "option", "fieldset":
		return true
	}
	return false
}

func isDisabledNode(n *html.Node) bool {
	if !isFormControl(n) {
		return false
	}
	if _, ok := nodeAttr(n, "disabled"); ok {
		return true
	}
	// Disabled fieldset ancestor, except descendants of its first legend.
	for p := n.Parent; p != nil; p = p.Parent {
		if p.Type == html.ElementNode && strings.ToLower(p.Data) == "fieldset" {
			if _, ok := nodeAttr(p, "disabled"); ok {
				// Find whether n is in the first legend element child.
				var firstLegend *html.Node
				for c := p.FirstChild; c != nil; c = c.NextSibling {
					if c.Type == html.ElementNode && strings.ToLower(c.Data) == "legend" {
						firstLegend = c
						break
					}
				}
				inLegend := false
				if firstLegend != nil {
					for q := n; q != nil; q = q.Parent {
						if q == firstLegend {
							inLegend = true
							break
						}
					}
				}
				if !inLegend {
					return true
				}
			}
		}
		// An option in a disabled optgroup is disabled, as is a
		// control in a disabled select context in practice; the
		// ancestor attr check below mirrors common expectations.
		if p.Type == html.ElementNode {
			tag := strings.ToLower(p.Data)
			if (tag == "optgroup" || tag == "select") && n != p {
				if _, ok := nodeAttr(p, "disabled"); ok && strings.ToLower(n.Data) == "option" {
					return true
				}
			}
		}
	}
	return false
}

// ---------- parser ----------

type selParser struct {
	s string
	i int
}

func (p *selParser) eof() bool { return p.i >= len(p.s) }

func (p *selParser) peek() (rune, int) {
	if p.eof() {
		return 0, 0
	}
	r, size := utf8.DecodeRuneInString(p.s[p.i:])
	return r, size
}

func (p *selParser) next() rune {
	r, size := p.peek()
	p.i += size
	return r
}

func (p *selParser) skipSpaces() bool {
	start := p.i
	for !p.eof() {
		r, _ := p.peek()
		if r != ' ' && r != '\t' && r != '\n' && r != '\r' && r != '\f' {
			break
		}
		p.next()
	}
	return p.i > start
}

func foundWhat(p *selParser) string {
	if p.eof() {
		return "EOF"
	}
	r, _ := p.peek()
	return string(r)
}

func isNameStart(r rune) bool {
	return r == '_' || r >= 0x80 || unicode.IsLetter(r)
}

func isNameChar(r rune) bool {
	return r == '_' || r == '-' || r >= 0x80 || unicode.IsLetter(r) || unicode.IsDigit(r)
}

func (p *selParser) parseEscape() (rune, error) {
	// p.i is just past the backslash.
	if p.eof() {
		return 0, fmt.Errorf("invalid escape sequence")
	}
	start := p.i
	hex := 0
	for hex < 6 && !p.eof() {
		r, _ := p.peek()
		if (r >= '0' && r <= '9') || (r >= 'a' && r <= 'f') || (r >= 'A' && r <= 'F') {
			p.next()
			hex++
		} else {
			break
		}
	}
	if hex > 0 {
		v, err := strconv.ParseInt(p.s[start:p.i], 16, 32)
		if err != nil || v == 0 || v > utf8.MaxRune || (v >= 0xD800 && v <= 0xDFFF) {
			v = utf8.RuneError
		}
		// One whitespace terminator is swallowed.
		if !p.eof() {
			if r, _ := p.peek(); r == ' ' || r == '\t' || r == '\n' || r == '\r' || r == '\f' {
				p.next()
			}
		}
		return rune(v), nil
	}
	r := p.next()
	if r == '\n' || r == '\r' {
		return 0, fmt.Errorf("invalid escape sequence")
	}
	return r, nil
}

func (p *selParser) parseIdentifier() (string, error) {
	var b strings.Builder
	// Optional leading '-'.
	if !p.eof() {
		if r, _ := p.peek(); r == '-' {
			b.WriteRune(p.next())
			if p.eof() {
				return "", fmt.Errorf("expected identifier, found EOF instead")
			}
			// A second '-' is allowed (custom-property style names).
			if r, _ := p.peek(); r == '-' {
				b.WriteRune(p.next())
			}
		}
	}
	if p.eof() {
		return "", fmt.Errorf("expected identifier, found EOF instead")
	}
	r, _ := p.peek()
	if r == '\\' {
		p.next()
		er, err := p.parseEscape()
		if err != nil {
			return "", err
		}
		b.WriteRune(er)
	} else if isNameStart(r) {
		b.WriteRune(p.next())
	} else {
		return "", fmt.Errorf("expected identifier, found %s instead", foundWhat(p))
	}
	for !p.eof() {
		r, _ := p.peek()
		if r == '\\' {
			p.next()
			er, err := p.parseEscape()
			if err != nil {
				return "", err
			}
			b.WriteRune(er)
		} else if isNameChar(r) {
			b.WriteRune(p.next())
		} else {
			break
		}
	}
	return b.String(), nil
}

func (p *selParser) parseName() (string, error) {
	var b strings.Builder
	for !p.eof() {
		r, _ := p.peek()
		if r == '\\' {
			p.next()
			er, err := p.parseEscape()
			if err != nil {
				return "", err
			}
			b.WriteRune(er)
		} else if isNameChar(r) {
			b.WriteRune(p.next())
		} else {
			break
		}
	}
	if b.Len() == 0 {
		return "", fmt.Errorf("expected name, found %s instead", foundWhat(p))
	}
	return b.String(), nil
}

func (p *selParser) parseString() (string, error) {
	quote := p.next() // ' or "
	var b strings.Builder
	for !p.eof() {
		r := p.next()
		if r == quote {
			return b.String(), nil
		}
		if r == '\\' {
			if p.eof() {
				return "", fmt.Errorf("EOF in string")
			}
			// CSS string escapes share identifier escape rules.
			p.i-- // step back over the backslash rune (ASCII)
			p.next()
			er, err := p.parseEscape()
			if err != nil {
				return "", fmt.Errorf("EOF in string")
			}
			b.WriteRune(er)
			continue
		}
		if r == '\n' {
			return "", fmt.Errorf("EOF in string")
		}
		b.WriteRune(r)
	}
	return "", fmt.Errorf("EOF in string")
}

func (p *selParser) parseAttribute() (func(*html.Node) bool, error) {
	p.next() // [
	p.skipSpaces()
	key, err := p.parseIdentifier()
	if err != nil {
		return nil, err
	}
	key = strings.ToLower(key)
	p.skipSpaces()
	if p.eof() {
		return nil, fmt.Errorf("unexpected EOF in attribute selector")
	}
	if r, _ := p.peek(); r == ']' {
		p.next()
		return func(n *html.Node) bool {
			_, ok := nodeAttr(n, key)
			return ok
		}, nil
	}
	var op string
	r, _ := p.peek()
	if r == '=' {
		p.next()
		op = "="
	} else if strings.ContainsRune("~|^$*!", r) {
		rn := p.next()
		if p.eof() {
			return nil, fmt.Errorf("unexpected EOF in attribute selector")
		}
		if r2, _ := p.peek(); r2 != '=' {
			rest := p.s[p.i-1:]
			if idx := strings.Index(rest, "]"); idx >= 0 {
				rest = rest[:idx]
			}
			return nil, fmt.Errorf("expected equality operator, found %q instead", rest)
		}
		p.next()
		op = string(rn) + "="
	} else {
		// Another identifier here produced an EOF-style error in
		// the reference implementation.
		if isNameStart(r) || r == '-' {
			return nil, fmt.Errorf("unexpected EOF in attribute selector")
		}
		rest := p.s[p.i:]
		if idx := strings.Index(rest, "]"); idx >= 0 {
			rest = rest[:idx]
		}
		return nil, fmt.Errorf("expected equality operator, found %q instead", rest)
	}
	p.skipSpaces()
	if p.eof() {
		return nil, fmt.Errorf("unexpected EOF in attribute selector")
	}
	var val string
	if r, _ := p.peek(); r == '\'' || r == '"' {
		val, err = p.parseString()
		if err != nil {
			return nil, err
		}
	} else {
		// Unquoted values are parsed as identifiers in the
		// reference; that rejects values starting with a digit.
		val, err = p.parseIdentifier()
		if err != nil {
			return nil, err
		}
	}
	p.skipSpaces()
	if p.eof() {
		return nil, fmt.Errorf("unexpected EOF in attribute selector")
	}
	insensitive := false
	if r, _ := p.peek(); r != ']' {
		if r == 'i' || r == 'I' {
			// 'I' was not verified against the reference for
			// every case; lowercase i certainly works. Treat
			// only a standalone i/I as the modifier by
			// consuming one rune and demanding ']'.
			insensitive = true
			p.next()
			p.skipSpaces()
			if p.eof() {
				return nil, fmt.Errorf("unexpected EOF in attribute selector")
			}
			if rr, _ := p.peek(); rr != ']' {
				return nil, fmt.Errorf("expected ']', found '%s' instead", string(rr))
			}
		} else {
			return nil, fmt.Errorf("expected ']', found '%s' instead", string(r))
		}
	}
	p.next() // ]

	eq := func(a, b string) bool {
		if insensitive {
			return strings.EqualFold(a, b)
		}
		return a == b
	}
	containsFold := func(a, b string) bool {
		if insensitive {
			return strings.Contains(strings.ToLower(a), strings.ToLower(b))
		}
		return strings.Contains(a, b)
	}
	prefixFold := func(a, b string) bool {
		if insensitive {
			return strings.HasPrefix(strings.ToLower(a), strings.ToLower(b))
		}
		return strings.HasPrefix(a, b)
	}
	suffixFold := func(a, b string) bool {
		if insensitive {
			return strings.HasSuffix(strings.ToLower(a), strings.ToLower(b))
		}
		return strings.HasSuffix(a, b)
	}
	return func(n *html.Node) bool {
		actual, ok := nodeAttr(n, key)
		if !ok {
			return false
		}
		switch op {
		case "=":
			return eq(actual, val)
		case "!=":
			return !eq(actual, val)
		case "~=":
			if val == "" || strings.Contains(val, " ") {
				return false
			}
			for _, f := range strings.Fields(actual) {
				if eq(f, val) {
					return true
				}
			}
			return false
		case "|=":
			return eq(actual, val) || prefixFold(actual, val+"-")
		case "^=":
			if val == "" {
				return false
			}
			return prefixFold(actual, val)
		case "$=":
			if val == "" {
				return false
			}
			return suffixFold(actual, val)
		case "*=":
			if val == "" {
				return false
			}
			return containsFold(actual, val)
		}
		return false
	}, nil
}

var pseudoElements = map[string]bool{
	"after": true, "backdrop": true, "before": true, "cue": true,
	"first-letter": true, "first-line": true, "grammar-error": true,
	"marker": true, "placeholder": true, "selection": true,
	"spelling-error": true,
}

func (p *selParser) expectOpenParen() error {
	if p.eof() {
		return fmt.Errorf("expected '(' but didn't find it")
	}
	if r, _ := p.peek(); r != '(' {
		return fmt.Errorf("expected '(' but didn't find it")
	}
	p.next()
	return nil
}

func (p *selParser) parseNth() (int, int, error) {
	p.skipSpaces()
	rest := p.s[p.i:]
	lower := strings.ToLower(rest)
	if strings.HasPrefix(lower, "odd") && (len(lower) == 3 || !isNameChar([]rune(lower)[3])) {
		p.i += 3
		p.skipSpaces()
		if p.eof() || p.s[p.i] != ')' {
			return 0, 0, fmt.Errorf("expected ')' but didn't find it")
		}
		p.next()
		return 2, 1, nil
	}
	if strings.HasPrefix(lower, "even") && (len(lower) == 4 || !isNameChar([]rune(lower)[4])) {
		p.i += 4
		p.skipSpaces()
		if p.eof() || p.s[p.i] != ')' {
			return 0, 0, fmt.Errorf("expected ')' but didn't find it")
		}
		p.next()
		return 2, 0, nil
	}
	sign := 1
	if !p.eof() {
		if r, _ := p.peek(); r == '+' || r == '-' {
			if r == '-' {
				sign = -1
			}
			p.next()
		}
	}
	if p.eof() {
		return 0, 0, fmt.Errorf("unexpected character while attempting to parse expression of form an+b")
	}
	var a, b int
	hasN := false
	r, _ := p.peek()
	if unicode.IsDigit(r) {
		start := p.i
		for !p.eof() {
			if rr, _ := p.peek(); unicode.IsDigit(rr) {
				p.next()
			} else {
				break
			}
		}
		num, _ := strconv.Atoi(p.s[start:p.i])
		if !p.eof() {
			if rr, _ := p.peek(); rr == 'n' || rr == 'N' {
				hasN = true
				a = sign * num
				p.next()
			}
		}
		if !hasN {
			a = 0
			b = sign * num
		}
	} else if r == 'n' || r == 'N' {
		hasN = true
		a = sign
		p.next()
	} else {
		return 0, 0, fmt.Errorf("unexpected character while attempting to parse expression of form an+b")
	}
	if hasN {
		p.skipSpaces()
		if !p.eof() {
			if rr, _ := p.peek(); rr == '+' || rr == '-' {
				bsign := 1
				if rr == '-' {
					bsign = -1
				}
				p.next()
				p.skipSpaces()
				if p.eof() {
					return 0, 0, fmt.Errorf("expected integer, but didn't find it")
				}
				if rr, _ := p.peek(); !unicode.IsDigit(rr) {
					return 0, 0, fmt.Errorf("expected integer, but didn't find it")
				}
				start := p.i
				for !p.eof() {
					if rr, _ := p.peek(); unicode.IsDigit(rr) {
						p.next()
					} else {
						break
					}
				}
				num, _ := strconv.Atoi(p.s[start:p.i])
				b = bsign * num
			}
		}
	}
	p.skipSpaces()
	if p.eof() || p.s[p.i] != ')' {
		return 0, 0, fmt.Errorf("expected ')' but didn't find it")
	}
	p.next()
	return a, b, nil
}

func (p *selParser) parseSimpleSelector() (Selector, error) {
	if p.eof() {
		return nil, fmt.Errorf("expected selector, found EOF instead")
	}
	comp := &compoundSelector{}
	r, _ := p.peek()
	if r == '*' {
		p.next()
	} else if r != '.' && r != '#' && r != '[' && r != ':' {
		ident, err := p.parseIdentifier()
		if err != nil {
			return nil, err
		}
		comp.tag = strings.ToLower(ident)
	}
	for !p.eof() {
		r, _ := p.peek()
		switch r {
		case '.':
			p.next()
			name, err := p.parseIdentifier()
			if err != nil {
				return nil, err
			}
			nn := name
			comp.conds = append(comp.conds, func(n *html.Node) bool {
				cls, ok := nodeAttr(n, "class")
				if !ok {
					return false
				}
				for _, f := range strings.Fields(cls) {
					if f == nn {
						return true
					}
				}
				return false
			})
		case '#':
			p.next()
			// A run of '#' behaves like repeated empty hash
			// prefixes in the reference.
			for !p.eof() {
				if rr, _ := p.peek(); rr == '#' {
					p.next()
				} else {
					break
				}
			}
			name, err := p.parseName()
			if err != nil {
				return nil, err
			}
			nn := name
			comp.conds = append(comp.conds, func(n *html.Node) bool {
				id, ok := nodeAttr(n, "id")
				return ok && id == nn
			})
		case '[':
			cond, err := p.parseAttribute()
			if err != nil {
				return nil, err
			}
			comp.conds = append(comp.conds, cond)
		case ':':
			cond, err := p.parsePseudo()
			if err != nil {
				return nil, err
			}
			comp.conds = append(comp.conds, cond)
		default:
			return comp, nil
		}
	}
	return comp, nil
}

func (p *selParser) parseComplexSelector(stopAtParen bool) (Selector, error) {
	sel, err := p.parseSimpleSelector()
	if err != nil {
		return nil, err
	}
	for {
		hadSpace := p.skipSpaces()
		if p.eof() {
			return sel, nil
		}
		r, _ := p.peek()
		if r == ',' || (stopAtParen && r == ')') {
			return sel, nil
		}
		var comb byte
		if r == '>' || r == '+' || r == '~' {
			comb = byte(r)
			p.next()
			p.skipSpaces()
			if p.eof() {
				return nil, fmt.Errorf("expected selector, found EOF instead")
			}
		} else if hadSpace {
			comb = ' '
		} else {
			return sel, nil
		}
		next, err := p.parseSimpleSelector()
		if err != nil {
			return nil, err
		}
		sel = &relativeSelector{combinator: comb, first: sel, second: next}
	}
}

func (p *selParser) parseGroup(stopAtParen bool) (Selector, error) {
	var group selectorGroup
	for {
		sel, err := p.parseComplexSelector(stopAtParen)
		if err != nil {
			return nil, err
		}
		group = append(group, sel)
		p.skipSpaces()
		if p.eof() {
			return group, nil
		}
		if stopAtParen {
			if r, _ := p.peek(); r == ')' {
				return group, nil
			}
		}
		if r, _ := p.peek(); r == ',' {
			p.next()
			p.skipSpaces()
			if p.eof() {
				return nil, fmt.Errorf("expected selector, found EOF instead")
			}
			continue
		}
		return group, nil
	}
}

func (p *selParser) parsePseudo() (func(*html.Node) bool, error) {
	p.next() // ':'
	isElement := false
	if !p.eof() {
		if r, _ := p.peek(); r == ':' {
			isElement = true
			p.next()
		}
	}
	if !isElement && p.eof() {
		return nil, fmt.Errorf("got empty pseudoclass (or pseudoelement)")
	}
	rawName, err := p.parseIdentifier()
	if err != nil {
		return nil, err
	}
	name := strings.ToLower(rawName)
	if pseudoElements[name] {
		return nil, fmt.Errorf("pseudo-element %s found, but pseudo-elements support is disabled", name)
	}
	if isElement {
		return nil, fmt.Errorf("unknown pseudoelement :%s", name)
	}

	switch name {
	case "nth-child", "nth-last-child", "nth-of-type", "nth-last-of-type":
		if err := p.expectOpenParen(); err != nil {
			return nil, err
		}
		a, b, err := p.parseNth()
		if err != nil {
			return nil, err
		}
		return func(n *html.Node) bool {
			sibs := elementSiblings(n)
			if strings.HasSuffix(name, "of-type") {
				tag := strings.ToLower(n.Data)
				var filtered []*html.Node
				for _, s := range sibs {
					if strings.ToLower(s.Data) == tag {
						filtered = append(filtered, s)
					}
				}
				sibs = filtered
			}
			idx := -1
			for i, s := range sibs {
				if s == n {
					idx = i + 1
					break
				}
			}
			if idx < 0 {
				return false
			}
			if strings.Contains(name, "last") {
				idx = len(sibs) - idx + 1
			}
			return nthMatches(a, b, idx)
		}, nil
	case "lang":
		if err := p.expectOpenParen(); err != nil {
			return nil, err
		}
		p.skipSpaces()
		lang, err := p.parseIdentifier()
		if err != nil {
			return nil, err
		}
		p.skipSpaces()
		if p.eof() {
			return nil, fmt.Errorf("unexpected EOF in pseudo selector")
		}
		if r, _ := p.peek(); r != ')' {
			return nil, fmt.Errorf("expected ')' but didn't find it")
		}
		p.next()
		return func(n *html.Node) bool {
			for x := n; x != nil; x = x.Parent {
				if x.Type != html.ElementNode {
					continue
				}
				if v, ok := nodeAttr(x, "lang"); ok {
					return strings.EqualFold(v, lang) || strings.HasPrefix(strings.ToLower(v), strings.ToLower(lang)+"-")
				}
				if v, ok := nodeAttr(x, "xml:lang"); ok {
					return strings.EqualFold(v, lang) || strings.HasPrefix(strings.ToLower(v), strings.ToLower(lang)+"-")
				}
			}
			return false
		}, nil
	case "contains", "containsown":
		if err := p.expectOpenParen(); err != nil {
			return nil, err
		}
		if p.eof() {
			return nil, fmt.Errorf("unmatched '('")
		}
		p.skipSpaces()
		var val string
		if r, _ := p.peek(); r == '\'' || r == '"' {
			val, err = p.parseString()
			if err != nil {
				return nil, err
			}
		} else {
			val, err = p.parseIdentifier()
			if err != nil {
				return nil, err
			}
		}
		p.skipSpaces()
		if p.eof() {
			return nil, fmt.Errorf("unexpected EOF in pseudo selector")
		}
		if r, _ := p.peek(); r != ')' {
			return nil, fmt.Errorf("expected ')' but didn't find it")
		}
		p.next()
		own := name == "containsown"
		return func(n *html.Node) bool {
			text := textContent(n)
			if own {
				text = ownTextContent(n)
			}
			return strings.Contains(strings.ToLower(text), strings.ToLower(val))
		}, nil
	case "matches":
		if err := p.expectOpenParen(); err != nil {
			return nil, err
		}
		// The raw argument up to the balancing close paren is a
		// regexp. Leading whitespace is skipped by the reference.
		p.skipSpaces()
		start := p.i
		depth := 0
		inClass := false
		escaped := false
		end := -1
		for i := start; i < len(p.s); i++ {
			c := p.s[i]
			if escaped {
				escaped = false
				continue
			}
			if c == '\\' {
				escaped = true
				continue
			}
			if inClass {
				if c == ']' {
					inClass = false
				}
				continue
			}
			switch c {
			case '[':
				inClass = true
			case '(':
				depth++
			case ')':
				if depth == 0 {
					end = i
				} else {
					depth--
				}
			}
			if end >= 0 {
				break
			}
		}
		if end < 0 {
			return nil, fmt.Errorf("EOF in regular expression")
		}
		raw := p.s[start:end]
		trimmed := strings.TrimSpace(raw)
		if trimmed == "" {
			return nil, fmt.Errorf("expected regular expression, found EOF instead")
		}
		if depth != 0 || inClass {
			return nil, fmt.Errorf("EOF in regular expression")
		}
		// A trailing ']' the scanner consumed as a selector
		// terminator, e.g. matches(Hello ]), is refused.
		if strings.HasSuffix(trimmed, "]") && !strings.Contains(trimmed, "[") {
			return nil, fmt.Errorf("expected ')' but didn't find it")
		}
		re, err := regexp.Compile(raw)
		if err != nil {
			if strings.Contains(err.Error(), "missing closing") || strings.Contains(err.Error(), "error parsing regexp: missing closing ]") {
				return nil, fmt.Errorf("EOF in regular expression")
			}
			return nil, err
		}
		p.i = end + 1
		return func(n *html.Node) bool {
			return re.MatchString(textContent(n))
		}, nil
	case "has", "haschild", "not":
		if err := p.expectOpenParen(); err != nil {
			return nil, err
		}
		p.skipSpaces()
		inner, err := p.parseGroup(true)
		if err != nil {
			return nil, err
		}
		p.skipSpaces()
		if p.eof() {
			return nil, fmt.Errorf("expected ')' but didn't find it")
		}
		if r, _ := p.peek(); r != ')' {
			return nil, fmt.Errorf("expected ')' but didn't find it")
		}
		p.next()
		switch name {
		case "not":
			return func(n *html.Node) bool { return !inner.Match(n) }, nil
		case "haschild":
			return func(n *html.Node) bool {
				for c := n.FirstChild; c != nil; c = c.NextSibling {
					if c.Type == html.ElementNode && inner.Match(c) {
						return true
					}
				}
				return false
			}, nil
		default:
			return func(n *html.Node) bool {
				found := false
				var rec func(*html.Node)
				rec = func(x *html.Node) {
					for c := x.FirstChild; c != nil && !found; c = c.NextSibling {
						if c.Type == html.ElementNode && inner.Match(c) {
							found = true
							return
						}
						rec(c)
					}
				}
				rec(n)
				return found
			}, nil
		}
	}

	// Non-functional pseudos.
	switch name {
	case "first-child":
		return func(n *html.Node) bool { sibs := elementSiblings(n); return len(sibs) > 0 && sibs[0] == n }, nil
	case "last-child":
		return func(n *html.Node) bool { sibs := elementSiblings(n); return len(sibs) > 0 && sibs[len(sibs)-1] == n }, nil
	case "first-of-type":
		return func(n *html.Node) bool {
			for _, s := range elementSiblings(n) {
				if strings.ToLower(s.Data) == strings.ToLower(n.Data) {
					return s == n
				}
			}
			return false
		}, nil
	case "last-of-type":
		return func(n *html.Node) bool {
			sibs := elementSiblings(n)
			for i := len(sibs) - 1; i >= 0; i-- {
				if strings.ToLower(sibs[i].Data) == strings.ToLower(n.Data) {
					return sibs[i] == n
				}
			}
			return false
		}, nil
	case "only-child":
		return func(n *html.Node) bool { return len(elementSiblings(n)) == 1 }, nil
	case "only-of-type":
		return func(n *html.Node) bool {
			count := 0
			for _, s := range elementSiblings(n) {
				if strings.ToLower(s.Data) == strings.ToLower(n.Data) {
					count++
				}
			}
			return count == 1
		}, nil
	case "root":
		return func(n *html.Node) bool { return n.Parent != nil && n.Parent.Type == html.DocumentNode }, nil
	case "empty":
		return func(n *html.Node) bool {
			for c := n.FirstChild; c != nil; c = c.NextSibling {
				if c.Type == html.ElementNode {
					return false
				}
				if c.Type == html.TextNode && len(c.Data) > 0 {
					return false
				}
			}
			return true
		}, nil
	case "link":
		return func(n *html.Node) bool {
			tag := strings.ToLower(n.Data)
			if tag != "a" && tag != "area" && tag != "link" {
				return false
			}
			_, ok := nodeAttr(n, "href")
			return ok
		}, nil
	case "visited", "target", "focus", "hover", "active":
		return func(n *html.Node) bool { return false }, nil
	case "enabled":
		return func(n *html.Node) bool { return isFormControl(n) && !isDisabledNode(n) }, nil
	case "disabled":
		return func(n *html.Node) bool { return isDisabledNode(n) }, nil
	case "checked":
		return func(n *html.Node) bool {
			tag := strings.ToLower(n.Data)
			if tag == "input" {
				_, ok := nodeAttr(n, "checked")
				return ok
			}
			if tag == "option" {
				_, ok := nodeAttr(n, "selected")
				return ok
			}
			return false
		}, nil
	case "input":
		return func(n *html.Node) bool {
			switch strings.ToLower(n.Data) {
			case "input", "select", "textarea", "button":
				return true
			}
			return false
		}, nil
	}
	return nil, fmt.Errorf("unknown pseudoclass or pseudoelement :%s", rawName)
}

// ParseSelectorGroup parses a (possibly comma-separated) selector.
func ParseSelectorGroup(s string) (Selector, error) {
	trimmed := strings.TrimSpace(s)
	if trimmed == "" {
		return nil, fmt.Errorf("empty string")
	}
	p := &selParser{s: trimmed}
	p.skipSpaces()
	group, err := p.parseGroup(false)
	if err != nil {
		return nil, err
	}
	p.skipSpaces()
	if !p.eof() {
		return nil, fmt.Errorf("parsing %q: %d bytes left over", trimmed, len(trimmed)-p.i)
	}
	return group, nil
}
