	if strings.HasSuffix(a, "\n") {
		b = strings.TrimLeft(b, " ")
	} else if strings.HasSuffix(a, " ") && strings.HasPrefix(b, " ") {
		b = strings.TrimLeft(b, " ")
	}
	return a + b
