func (c *converter) updateLineCtx(ctx rctx, f frag) rctx {
	if f.kind == fragBreak {
		ctx.afterHardBreak = ctx.lineHasContent
		ctx.atLineStart = true
		ctx.linePrefix = ""
		ctx.lineHasContent = false
		return ctx
	}
	if f.kind == fragBlock {
		ctx.atLineStart = true
		ctx.linePrefix = ""
		ctx.afterHardBreak = false
		ctx.lineHasContent = false
		return ctx
	}
	if f.kind == fragEmpty {
		return ctx
	}
	s := f.s
	if strings.Contains(s, "\n") {
		lastNL := strings.LastIndex(s, "\n")
		after := s[lastNL+1:]
		// Was there a blank line immediately before the last newline?
		blankBefore := strings.Contains(s, "\n\n") && strings.HasSuffix(s[:lastNL+1], "\n\n")
		beforeLast := s[:lastNL]
		prevLine := beforeLast
		if idx := strings.LastIndex(beforeLast, "\n"); idx >= 0 {
			prevLine = beforeLast[idx+1:]
		}
		ctx.afterHardBreak = !blankBefore && strings.TrimSpace(prevLine) != ""
		ctx.linePrefix = strings.TrimLeft(after, " ")
		ctx.atLineStart = ctx.linePrefix == ""
		ctx.lineHasContent = ctx.linePrefix != ""
		if ctx.lineHasContent {
			ctx.afterHardBreak = false
		}
