func mergeWrappedFrags(left, right frag) (frag, bool) {
	if left.wrap == nil || right.wrap == nil {
		return frag{}, false
	}
	if strings.Contains(left.s, "\n") || strings.Contains(right.s, "\n") {
		return frag{}, false
	}
	mergedInner := mergeInnerFrags(left.wrap.innerFrag, right.wrap.innerFrag)
	var innerText string
	var innerFrag *frag
	if mergedInner != nil {
		innerText = mergedInner.s
		innerFrag = mergedInner
	} else {
		innerText = appendInline(left.wrap.inner, right.wrap.inner)
		innerFrag = &frag{s: innerText, kind: fragInline}
	}
	wrapped := left.wrap.delim + innerText + left.wrap.delim
	s := wrapped
	if left.wrap.lead {
		s = " " + s
	}
	if right.wrap.trail {
		s = s + " "
	}
	out := frag{
		s: s, kind: fragInline, node: left.node, mergeClass: left.mergeClass,
		wrap: &wrapInfo{delim: left.wrap.delim, inner: innerText, innerFrag: innerFrag, lead: left.wrap.lead, trail: right.wrap.trail},
	}
	return out, true
