func mergeInnerFrags(left, right *frag) *frag {
	if left == nil || right == nil {
		return nil
	}
	if left.wrap != nil && right.wrap != nil {
		if merged, ok := mergeWrappedFrags(*left, *right); ok {
			return &merged
		}
		return nil
	}
	return nil
}

func mergeAdjacentFrags(frags []frag, conv *converter) []frag {
	var out []frag
	for _, f := range frags {
		if (f.mergeClass == "emphasis" || f.mergeClass == "strike") && f.wrap != nil {
			// Look back for a mergeable predecessor, allowing
			// removable empty fragments in between.
			idx := len(out) - 1
			for idx >= 0 && fragIsRemovableEmpty(out[idx]) {
				idx--
			}
			if idx >= 0 && out[idx].mergeClass == f.mergeClass && out[idx].wrap != nil {
				if merged, ok := mergeWrappedFrags(out[idx], f); ok {
					out = append(out[:idx], merged)
					continue
				}
			}
		}
		if f.mergeClass == "code" && f.kind != fragEmpty {
			idx := len(out) - 1
			for idx >= 0 && fragIsRemovableEmpty(out[idx]) {
				idx--
			}
			if idx >= 0 && out[idx].mergeClass == "code" && out[idx].kind != fragEmpty {
				combined := out[idx].codeRaw + f.codeRaw
				formatted, _ := formatCodeSpan(combined)
				if formatted != "" {
					merged := frag{s: formatted, kind: fragInline, node: out[idx].node, mergeClass: "code", codeRaw: combined}
					out = append(out[:idx], merged)
					continue
				}
			}
		}
		out = append(out, f)
	}
	return out
}

func (c *converter) renderNodeList(nodes []*html.Node, ctx rctx) frag {
	var frags []frag
	curCtx := ctx
	for _, n := range nodes {
		f := c.renderNode(n, curCtx)
		if f.node == nil {
			f.node = n
		}
		if f.mergeClass == "" {
			f.mergeClass = mergeClassForNode(n, c)
		}
		frags = append(frags, f)
		curCtx = c.updateLineCtx(curCtx, f)
	}
	frags = mergeAdjacentFrags(frags, c)
	return c.joinFragments(frags)
}

func (c *converter) joinFragments(frags []frag) frag {
	// Determine the sole effective fragment, if any.
	var sole *frag
	effective := 0
	for i := range frags {
		f := frags[i]
		if f.kind == fragEmpty {
			continue
		}
		if f.kind == fragInline && strings.TrimSpace(f.s) == "" {
			continue
		}
		effective++
		cp := frags[i]
		sole = &cp
	}
	if effective != 1 {
		sole = nil
	}

	hasBlock := false
	for _, f := range frags {
		if f.kind == fragBlock {
			hasBlock = true
		}
	}
	// Detect a run of 2+ breaks (allowing whitespace/empty between).
	hasDoubleBreak := false
	breakRun := 0
	for _, f := range frags {
		if f.kind == fragBreak {
			breakRun++
			if breakRun >= 2 {
				hasDoubleBreak = true
			}
			continue
		}
		if f.kind == fragEmpty || (f.kind == fragInline && strings.TrimSpace(f.s) == "") {
			continue
		}
		breakRun = 0
	}

	if !hasBlock && !hasDoubleBreak {
		var s string
		for _, f := range frags {
			if f.kind == fragBreak {
				s = strings.TrimRight(s, " ")
				if strings.TrimSpace(s) != "" {
					s += "  \n"
				}
				continue
			}
			if f.kind == fragEmpty {
				continue
			}
			s = appendInline(s, f.s)
		}
		if strings.TrimSpace(s) == "" && !strings.Contains(s, " ") {
			return frag{kind: fragEmpty, sole: sole}
		}
		kind := fragInline
		if strings.TrimSpace(s) == "" {
			// Preserve a lone space as an inline fragment.
			s = " "
		}
		return frag{s: s, kind: kind, sole: sole}
	}

	var segments []string
	var cur string
	pendingBreaks := 0
	flush := func() {
		t := trimBlockString(cur)
		if t != "" {
			segments = append(segments, t)
		}
		cur = ""
	}
	for _, f := range frags {
		if f.kind == fragBreak {
			pendingBreaks++
			continue
		}
		if f.kind == fragEmpty {
			continue
		}
		if f.kind == fragInline && strings.TrimSpace(f.s) == "" {
			if pendingBreaks == 0 && cur != "" {
				cur = appendInline(cur, " ")
			}
			continue
		}
		if f.kind == fragBlock {
			pendingBreaks = 0
			flush()
			t := trimBlockString(f.s)
			if t != "" {
				segments = append(segments, t)
			}
			continue
		}
		// Inline with content.
		if pendingBreaks >= 2 {
			flush()
			cur = appendInline(cur, f.s)
		} else if pendingBreaks == 1 {
			if strings.TrimSpace(cur) != "" {
				cur = strings.TrimRight(cur, " ") + "  \n" + strings.TrimLeft(f.s, " ")
			} else {
				cur = appendInline(cur, f.s)
			}
		} else {
			cur = appendInline(cur, f.s)
		}
		pendingBreaks = 0
	}
	flush()
	if len(segments) == 0 {
		return frag{kind: fragEmpty, sole: sole}
	}
	return frag{s: strings.Join(segments, "\n\n"), kind: fragBlock, sole: sole}
}

func (c *converter) renderChildren(n *html.Node, ctx rctx) frag {
	return c.renderNodeList(childNodes(n), ctx)
}
