			// Look back for a mergeable predecessor, allowing
			// removable empty fragments in between.
			idx := len(out) - 1
			for idx >= 0 && fragIsRemovableEmpty(out[idx]) {
				idx--
			}
			if idx >= 0 && out[idx].mergeClass == f.mergeClass && out[idx].wrap != nil {
				if merged, ok := mergeWrappedFrags(out[idx], f); ok {
					out = append(out[:idx], merged)
					continue
				}
			}
		}
		if f.mergeClass == "code" && f.kind != fragEmpty {
			idx := len(out) - 1
			for idx >= 0 && fragIsRemovableEmpty(out[idx]) {
				idx--
			}
			if idx >= 0 && out[idx].mergeClass == "code" && out[idx].kind != fragEmpty {
				combined := out[idx].codeRaw + f.codeRaw
				formatted, _ := formatCodeSpan(combined)
				if formatted != "" {
					merged := frag{s: formatted, kind: fragInline, node: out[idx].node, mergeClass: "code", codeRaw: combined}
					out = append(out[:idx], merged)
					continue
				}
			}
		}
		out = append(out, f)
	}
