	var cur string
	pendingBreaks := 0
	flush := func() {
		t := trimBlockString(cur)
		if t != "" {
			segments = append(segments, t)
		}
		cur = ""
	}
	for _, f := range frags {
		if f.kind == fragBreak {
			pendingBreaks++
			continue
		}
		if f.kind == fragEmpty {
			continue
		}
		if f.kind == fragInline && strings.TrimSpace(f.s) == "" {
			if pendingBreaks == 0 && cur != "" {
				cur = appendInline(cur, " ")
			}
			continue
		}
		if f.kind == fragBlock {
			pendingBreaks = 0
			flush()
			t := trimBlockString(f.s)
			if t != "" {
				segments = append(segments, t)
			}
			continue
		}
		// Inline with content.
		if pendingBreaks >= 2 {
			flush()
			cur = appendInline(cur, f.s)
		} else if pendingBreaks == 1 {
			if strings.TrimSpace(cur) != "" {
				cur = strings.TrimRight(cur, " ") + "  \n" + strings.TrimLeft(f.s, " ")
			} else {
				cur = appendInline(cur, f.s)
			}
		} else {
			cur = appendInline(cur, f.s)
		}
		pendingBreaks = 0
	}
	flush()
	if len(segments) == 0 {
		return frag{kind: fragEmpty, sole: sole}
	}
	return frag{s: strings.Join(segments, "\n\n"), kind: fragBlock, sole: sole}
}

func (c *converter) renderChildren(n *html.Node, ctx rctx) frag {
	return c.renderNodeList(childNodes(n), ctx)
}
