func getAttr(n *html.Node, key string) (string, bool) {
	for _, a := range n.Attr {
		if a.Key == key {
			return a.Val, true
		}
	}
	return "", false
}

func findFirstElement(n *html.Node, tag string) *html.Node {
	if n.Type == html.ElementNode && tagName(n) == tag {
		return n
	}
	for ch := n.FirstChild; ch != nil; ch = ch.NextSibling {
		if found := findFirstElement(ch, tag); found != nil {
			return found
		}
	}
	return nil
}

func (c *converter) convert(input []byte) (string, error) {
	doc, err := html.Parse(bytes.NewReader(input))
	if err != nil {
		return "", err
	}
	c.visited = make(map[*html.Node]bool)
	c.excludeSet = make(map[*html.Node]bool)
	c.includeMode = len(c.includeSelectors) > 0

	// Collect all element nodes once, in document order.
	var all []*html.Node
	var collect func(*html.Node)
	collect = func(n *html.Node) {
		if n.Type == html.ElementNode {
			all = append(all, n)
		}
		for ch := n.FirstChild; ch != nil; ch = ch.NextSibling {
			collect(ch)
		}
	}
	collect(doc)
	for _, n := range all {
		for _, sel := range c.excludeSelectors {
			if sel.Match(n) {
				c.excludeSet[n] = true
				break
			}
		}
	}

	rootCtx := rctx{atLineStart: true, visit: c.includeMode}
	var out frag
	if c.includeMode {
		var roots []*html.Node
		for _, n := range all {
			if c.excludeSet[n] {
				continue
			}
			for _, sel := range c.includeSelectors {
				if sel.Match(n) {
					roots = append(roots, n)
					break
				}
			}
		}
		out = c.renderNodeList(roots, rootCtx)
	} else {
		body := findFirstElement(doc, "body")
		if body == nil {
			return "", nil
