		case ']':
			if ctx.link && !marks[idx] {
				b.WriteByte('\\')
			}
			b.WriteString(raw)
		case '|':
			if ctx.tableCell && !marks[idx] {
				b.WriteByte('\\')
			}
			b.WriteString(raw)
		default:
			b.WriteString(raw)
		}
		idx++
	}
	return b.String()
}

func allDigits(s string) bool {
	if s == "" {
		return false
	}
	for _, r := range s {
		if !unicode.IsDigit(r) {
			return false
		}
	}
	return true
}
