{"command":"cat > escape.go <<'GO'
package main

import (
	"strings"
	"unicode"
	"unicode/utf8"

	"golang.org/x/net/html"
)

// nextVisibleRune returns the first rune that would be rendered after this
// text node: a real text rune, '\n' for a break or block boundary, or a
// placeholder non-space rune for atomic inline elements. has is false at
// the end of the enclosing block.
func nextVisibleRune(from *html.Node, conv *converter) (rune, bool) {
	cur := from
	for {
		// Move to the next node in document order, ascending
		// through inline ancestors only.
		var next *html.Node
		if cur.NextSibling != nil {
			next = cur.NextSibling
		} else {
			p := cur.Parent
			for p != nil {
				if p.Type == html.ElementNode {
					tag := tagName(p)
					if blockTags[tag] || tag == "body" || tag == "html" || tag == "td" || tag == "th" || tag == "li" || tag == "tr" || tag == "caption" {
						return 0, false
					}
				}
				if p.NextSibling != nil {
					next = p.NextSibling
					break
				}
				p = p.Parent
			}
			if next == nil {
				return 0, false
			}
		}
		// Examine next, descending into transparent elements.
		node := next
		for node != nil {
			if conv != nil && conv.isExcluded(node) {
				break
			}
			switch node.Type {
			case html.TextNode:
				if len(node.Data) == 0 {
					break
				}
				r, _ := utf8.DecodeRuneInString(collapseASCIIWhitespace(node.Data))
				return r, true
			case html.CommentNode, html.DoctypeNode:
				goto advance
			case html.ElementNode:
				tag := tagName(node)
				if ignoredTags[tag] {
					goto advance
				}
				if tag == "br" || tag == "hr" || blockTags[tag] {
					return '\n', true
				}
				switch tag {
				case "img", "image":
					if src, ok := getAttr(node, "src"); ok && strings.TrimSpace(src) != "" {
						return '!', true
					}
					goto advance
				case "a":
					return '[', true
				case "code", "kbd", "samp", "var", "tt":
					return '`', true
				case "strong", "b":
					return '*', true
				case "em", "i":
					return '*', true
				case "wbr", "input", "source", "track", "meta", "link", "col", "area", "embed":
					goto advance
				}
				if node.FirstChild != nil {
					node = node.FirstChild
					continue
				}
				goto advance
			default:
				goto advance
			}
		}
	advance:
		cur = next
		// If next was an element we need to skip its whole subtree:
		// move cur to the last descendant so the next iteration
		// ascends past it.
		for cur.LastChild != nil {
			cur = cur.LastChild
		}
	}
}

// lookaheadText gathers upcoming plain text (collapsing whitespace),
// stopping at a break or block boundary. It is used for line-start
// pattern detection across transparent inline elements.
func lookaheadText(from *html.Node, conv *converter, limit int) string {
	var b strings.Builder
	cur := from
	for b.Len() < limit {
		var next *html.Node
		if cur.NextSibling != nil {
			next = cur.NextSibling
		} else {
			p := cur.Parent
			for p != nil {
				if p.Type == html.ElementNode {
					tag := tagName(p)
					if blockTags[tag] || tag == "body" || tag == "html" || tag == "a" || tag == "strong" || tag == "b" || tag == "em" || tag == "i" || isCodeTag(tag) {
						return b.String()
					}
				}
				if p.NextSibling != nil {
					next = p.NextSibling
					break
				}
				p = p.Parent
			}
			if next == nil {
				return b.String()
			}
		}
		stop := false
		var walk func(*html.Node)
		walk = func(x *html.Node) {
			if stop || b.Len() >= limit {
				return
			}
			if conv != nil && conv.isExcluded(x) {
				return
			}
			if x.Type == html.TextNode {
				b.WriteString(collapseASCIIWhitespace(x.Data))
				return
			}
			if x.Type == html.ElementNode {
				tag := tagName(x)
				if ignoredTags[tag] {
					return
				}
				if tag == "br" || tag == "hr" || blockTags[tag] || tag == "a" || isCodeTag(tag) || tag == "img" {
					stop = true
					return
				}
				if tag == "strong" || tag == "b" || tag == "em" || tag == "i" {
					stop = true
					return
				}
			}
			for ch := x.FirstChild; ch != nil; ch = ch.NextSibling {
				walk(ch)
			}
		}
		walk(next)
		if stop {
			return b.String()
		}
		cur = next
		for cur.LastChild != nil {
			cur = cur.LastChild
		}
	}
	return b.String()
}

func isSpaceRune(r rune) bool { return unicode.IsSpace(r) }

// escapeText applies the "smart" escaping rules to a single, already
// whitespace-collapsed text node.
func (c *converter) escapeText(node *html.Node, text string, ctx rctx) string {
	if text == "" {
		return ""
	}
	runes := []rune(text)
	// Byte offset of each rune, plus a sentinel.
	offsets := make([]int, len(runes)+1)
	pos := 0
	for i := range runes {
		offsets[i] = pos
		_, size := utf8.DecodeRuneInString(text[pos:])
		if size == 0 {
			size = 1
		}
		pos += size
	}
	offsets[len(runes)] = pos

	marks := make(map[int]bool) // rune indexes to prefix with a backslash

	nextR, hasNext := nextVisibleRune(node, c)
	lookahead := lookaheadText(node, c, 64)
	lookRunes := []rune(lookahead)

	runeAfter := func(idx int) (rune, bool) {
		if idx < len(runes) {
			return runes[idx], true
		}
		if k := idx - len(runes); k < len(lookRunes) {
			return lookRunes[k], true
		}
		return nextR, hasNext
	}

	// Locate the first non-space rune in this node.
	firstNonSpace := 0
	for firstNonSpace < len(runes) && isSpaceRune(runes[firstNonSpace]) {
		firstNonSpace++
	}

	linePrefix := ctx.linePrefix
	prefixIsDigits := linePrefix != "" && allDigits(linePrefix)
	atStart := ctx.atLineStart && strings.TrimSpace(linePrefix) == ""

	initialFenceStart := -1
	initialFenceLen := 0

	if ctx.afterHardBreak && !ctx.blockquote {
		// Setext-heading guard: a line after a hard break that
		// starts with '=' or '-' has its first character escaped.
		if atStart && firstNonSpace < len(runes) {
			if r := runes[firstNonSpace]; r == '=' || r == '-' {
				marks[firstNonSpace] = true
			}
		}
	}

	if atStart && firstNonSpace < len(runes) {
		i := firstNonSpace
		// Fenced code.
		if runes[i] == '`' || runes[i] == '~' {
			j := i
			for j < len(runes) && runes[j] == runes[i] {
				j++
			}
			runLen := j - i
			if runLen < 3 {
				// Count runes in the lookahead too.
				all := append(append([]rune{}, runes[i:]...), lookRunes...)
				k := 0
				for k < len(all) && all[k] == runes[i] {
					k++
				}
				runLen = k
			}
			if runLen >= 3 {
				marks[i] = true
				if runes[i] == '`' {
					initialFenceStart = i
					initialFenceLen = j - i
				}
			}
		}
		// ATX heading.
		if runes[i] == '#' {
			j := i
			for j < len(runes) && runes[j] == '#' {
				j++
			}
			count := j - i
			if count <= 6 {
				if nr, ok := runeAfter(j); !ok || isSpaceRune(nr) {
					// Only when the whole run lives in this
					// node or the run truly ends here.
					if j < len(runes) || len(lookRunes) == 0 || lookRunes[0] != '#' {
						marks[i] = true
					}
				}
			}
		}
		// Bullet list.
		if runes[i] == '-' || runes[i] == '+' || runes[i] == '*' {
			if nr, ok := runeAfter(i + 1); !ok || isSpaceRune(nr) {
				// Single marker only: the next rune being a
				// space or the end means the run length is 1.
				marks[i] = true
			}
		}
		// Ordered list.
		if unicode.IsDigit(runes[i]) {
			j := i
			for j < len(runes) && unicode.IsDigit(runes[j]) {
				j++
			}
			if j < len(runes) && (runes[j] == '.' || runes[j] == ')') {
				if nr, ok := runeAfter(j + 1); !ok || isSpaceRune(nr) {
					marks[j] = true
				}
			} else if j == len(runes) && len(lookRunes) >= 1 && (lookRunes[0] == '.' || lookRunes[0] == ')') {
				// Punctuation lives in the next node; nothing
				// to mark in this node.
			}
		}
		// Thematic break: the rest of the line is only spaces and
		// 3+ copies of one of - _ *.
		{
			rest := append(append([]rune{}, runes[i:]...), lookRunes...)
			var ch rune
			count := 0
			ok := true
			atLineEnd := !hasNext || nextR == '\n'
			for _, r := range rest {
				if isSpaceRune(r) {
					continue
				}
				if r != '-' && r != '_' && r != '*' {
					ok = false
					break
				}
				if ch == 0 {
					ch = r
				} else if ch != r {
					ok = false
					break
				}
				count++
			}
			if ok && count >= 3 && atLineEnd {
				marks[i] = true
			}
		}
	}

	// Ordered-list punctuation that starts this node while the digits
	// were rendered by a previous sibling.
	if prefixIsDigits && firstNonSpace == 0 && len(runes) > 0 && (runes[0] == '.' || runes[0] == ')') {
		if nr, ok := runeAfter(1); !ok || isSpaceRune(nr) {
			marks[0] = true
		}
	}

	var b strings.Builder
	for idx := 0; idx < len(runes); {
		r := runes[idx]
		raw := text[offsets[idx]:offsets[idx+1]]

		if r == '*' || r == '_' {
			j := idx
			for j < len(runes) && runes[j] == r {
				j++
			}
			nr, ok := runeAfter(j)
			escapeAll := ok && !isSpaceRune(nr)
			for k := idx; k < j; k++ {
				if marks[k] || escapeAll || k < j-1 {
					b.WriteByte('\\')
				}
				b.WriteString(text[offsets[k]:offsets[k+1]])
			}
			idx = j
			continue
		}

		if marks[idx] {
			b.WriteByte('\\')
		}
		switch r {
		case '<':
			b.WriteString("&lt;")
		case '>':
			b.WriteString("&gt;")
		case '\\':
			b.WriteString("\\\\")
		case '`':
			if initialFenceStart >= 0 && idx >= initialFenceStart && idx < initialFenceStart+initialFenceLen {
				// Only the first backtick (already marked).
				b.WriteString(raw)
			} else {
				if !marks[idx] {
					b.WriteByte('\\')
				}
				b.WriteString(raw)
			}
		case '[':
			escape := ctx.link
			if !escape {
				rest := string(runes[idx+1:]) + lookahead
				if strings.Contains(rest, "]") {
					escape = true
				}
			}
			if escape && !marks[idx] {
				b.WriteByte('\\')
			}
			b.WriteString(raw)
		case ']':
			if ctx.link && !marks[idx] {
				b.WriteByte('\\')
			}
			b.WriteString(raw)
		case '|':
			if ctx.tableCell && !marks[idx] {
				b.WriteByte('\\')
			}
			b.WriteString(raw)
		default:
			b.WriteString(raw)
		}
		idx++
	}
	return b.String()
}

func allDigits(s string) bool {
	if s == "" {
		return false
	}
	for _, r := range s {
		if !unicode.IsDigit(r) {
			return false
		}
	}
	return true
}
GO
"}

{"command":"cat > render.go <<'GO'
package main

import (
	"regexp"
	"strconv"
	"strings"
	"unicode/utf8"

	"golang.org/x/net/html"
)

func (c *converter) renderNode(n *html.Node, ctx rctx) frag {
	if n == nil {
		return frag{kind: fragEmpty}
	}
	if c.isExcluded(n) {
		return frag{kind: fragEmpty, node: n}
	}
	if ctx.visit && c.visited != nil {
		if c.visited[n] {
			return frag{kind: fragEmpty, node: n}
		}
		c.visited[n] = true
	}

	switch n.Type {
	case html.TextNode:
		if ctx.code {
			return frag{s: collapseASCIIWhitespace(n.Data), kind: fragInline, node: n}
		}
		s := c.escapeText(n, collapseASCIIWhitespace(n.Data), ctx)
		if s == "" {
			return frag{kind: fragEmpty, node: n}
		}
		return frag{s: s, kind: fragInline, node: n}
	case html.CommentNode, html.DoctypeNode:
		return frag{kind: fragEmpty, node: n}
	case html.DocumentNode:
		body := findFirstElement(n, "body")
		if body == nil {
			return frag{kind: fragEmpty, node: n}
		}
		return c.renderNode(body, ctx)
	case html.ElementNode:
		// handled below
	default:
		return frag{kind: fragEmpty, node: n}
	}

	tag := tagName(n)
	if ignoredTags[tag] {
		return frag{kind: fragEmpty, node: n}
	}

	switch tag {
	case "html":
		body := findFirstElement(n, "body")
		if body == nil {
			return frag{kind: fragEmpty, node: n}
		}
		return c.renderNode(body, ctx)
	case "head":
		return frag{kind: fragEmpty, node: n}
	case "body":
		return c.renderChildren(n, ctx.forBlock())
	case "br":
		return frag{s: "  \n", kind: fragBreak, node: n}
	case "hr":
		if ctx.code {
			return frag{kind: fragEmpty, node: n}
		}
		if ctx.inline {
			return frag{kind: fragEmpty, node: n}
		}
		return frag{s: "* * *", kind: fragBlock, node: n}
	case "img", "image":
		return c.renderImage(n, ctx)
	case "a":
		return c.renderLink(n, ctx)
	case "strong", "b":
		if ctx.code {
			return frag{s: c.extractText(n), kind: fragInline, node: n}
		}
		if ctx.strong {
			f := c.renderChildren(n, ctx)
			f.node = n
			return f
		}
		return c.renderEmphasis(n, ctx, c.strongDelimiter, true)
	case "em", "i":
		if ctx.code {
			return frag{s: c.extractText(n), kind: fragInline, node: n}
		}
		if ctx.em {
			f := c.renderChildren(n, ctx)
			f.node = n
			return f
		}
		return c.renderEmphasis(n, ctx, "*", false)
	case "del", "s", "strike":
		if c.pluginStrikethrough {
			if ctx.strike {
				f := c.renderChildren(n, ctx)
				f.node = n
				return f
			}
			childCtx := ctx.forWrapper("~~")
			childCtx.strike = true
			child := c.renderChildren(n, childCtx)
			return wrapInlineFrag(child, "~~", n, "strike")
		}
		f := c.renderChildren(n, ctx)
		f.node = n
		return f
	case "code", "kbd", "samp", "var", "tt":
		return c.renderCodeSpan(n, ctx)
	case "pre":
		return c.renderPre(n, ctx)
	case "h1", "h2", "h3", "h4", "h5", "h6":
		return c.renderHeading(n, ctx, int(tag[1]-'0'))
	case "blockquote":
		return c.renderBlockquote(n, ctx)
	case "ul", "ol":
		return c.renderList(n, ctx)
	case "table":
		if c.pluginTable {
			return c.renderTable(n, ctx)
		}
		child := c.renderChildren(n, ctx.forBlock())
		if trimBlockString(child.s) == "" {
			return frag{kind: fragEmpty, node: n}
		}
		return frag{s: trimBlockString(child.s), kind: fragBlock, node: n}
	case "tr":
		if ctx.tableFallback {
			child := c.renderChildren(n, ctx)
			if trimBlockString(child.s) == "" {
				return frag{kind: fragEmpty, node: n}
			}
			return frag{s: trimBlockString(child.s), kind: fragBlock, node: n}
		}
		f := c.renderChildren(n, ctx)
		f.node = n
		return f
	case "p":
		childCtx := ctx.forBlock()
		childCtx.inline = true
		child := c.renderChildren(n, childCtx)
		if trimBlockString(child.s) == "" {
			return frag{kind: fragEmpty, node: n}
		}
		return frag{s: trimBlockString(child.s), kind: fragBlock, node: n}
	}

	if blockTags[tag] {
		child := c.renderChildren(n, ctx.forBlock())
		if trimBlockString(child.s) == "" {
			return frag{kind: fragEmpty, node: n}
		}
		return frag{s: trimBlockString(child.s), kind: fragBlock, node: n}
	}
	// Inline / unknown element: transparent.
	f := c.renderChildren(n, ctx)
	f.node = n
	// A transparent wrapper that produced a block keeps block kind;
	// an inline result keeps its spaces for wrapper handling.
	return f
}

// ---------- emphasis ----------

func wrapDelimitedLine(content, delim string) string {
	hardSuffix := ""
	if strings.HasSuffix(content, "  ") {
		hardSuffix = "  "
		content = strings.TrimSuffix(content, "  ")
	}
	lead := strings.HasPrefix(content, " ")
	trail := strings.HasSuffix(content, " ")
	trimmed := strings.Trim(content, " ")
	if trimmed == "" {
		return content + hardSuffix
	}
	out := ""
	if lead {
		out += " "
	}
	out += delim + trimmed + delim
	if trail && hardSuffix == "" {
		out += " "
	}
	out += hardSuffix
	return out
}

func wrapDelimitedText(s, delim string, skipBackslashLine bool) string {
	lines := strings.Split(s, "\n")
	for i, line := range lines {
		if strings.TrimSpace(line) == "" {
			continue
		}
		if skipBackslashLine && line == "\\" {
			continue
		}
		lines[i] = wrapDelimitedLine(line, delim)
	}
	return strings.Join(lines, "\n")
}

func wrapInlineFrag(child frag, delim string, node *html.Node, mergeClass string) frag {
	s := child.s
	if strings.TrimSpace(s) == "" {
		if strings.Contains(s, " ") {
			return frag{s: " ", kind: fragInline, node: node}
		}
		return frag{kind: fragEmpty, node: node}
	}
	if !strings.Contains(s, "\n") {
		lead := strings.HasPrefix(s, " ")
		trail := strings.HasSuffix(s, " ")
		inner := strings.Trim(s, " ")
		wrapped := delim + inner + delim
		out := wrapped
		if lead {
			out = " " + out
		}
		if trail {
			out += " "
		}
		var innerFrag *frag
		if child.sole != nil {
			innerFrag = child.sole
		} else {
			innerFrag = &frag{s: inner, kind: fragInline}
		}
		return frag{
			s: out, kind: fragInline, node: node, mergeClass: mergeClass,
			wrap: &wrapInfo{delim: delim, inner: inner, innerFrag: innerFrag, lead: lead, trail: trail},
		}
	}
	lead := strings.HasPrefix(s, " ")
	trail := strings.HasSuffix(s, " ")
	core := strings.Trim(s, " \n")
	wrapped := wrapDelimitedText(core, delim, false)
	out := wrapped
	if lead {
		out = " " + out
	}
	if trail {
		out += " "
	}
	kind := fragInline
	if strings.Contains(core, "\n\n") || child.kind == fragBlock {
		kind = fragBlock
	}
	return frag{s: out, kind: kind, node: node, mergeClass: mergeClass}
}

func (c *converter) renderEmphasis(n *html.Node, ctx rctx, delim string, isStrong bool) frag {
	// A lone link child gets the emphasis inside the link text.
	if !ctx.suppressLinkSpecial {
		eff := effectiveChildren(n)
		if len(eff) == 1 && eff[0].Type == html.ElementNode && tagName(eff[0]) == "a" {
			linkCtx := ctx
			linkCtx.linkWrapDelim = delim
			if isStrong {
				linkCtx.strong = true
			} else {
				linkCtx.em = true
			}
			f := c.renderNode(eff[0], linkCtx)
			// The wrapper's own leading/trailing whitespace was
			// trimmed by the link; a link fragment is inline.
			return f
		}
	}
	childCtx := ctx.forWrapper(delim)
	if isStrong {
		childCtx.strong = true
	} else {
		childCtx.em = true
	}
	child := c.renderChildren(n, childCtx)
	return wrapInlineFrag(child, delim, n, "emphasis")
}

// ---------- links and images ----------

func titlePart(title string) string {
	if title == "" {
		return ""
	}
	title = strings.NewReplacer("\r\n", " ", "\n", " ", "\r", " ").Replace(title)
	if strings.Contains(title, "\"") && !strings.Contains(title, "'") {
		return " '" + title + "'"
	}
	title = strings.ReplaceAll(title, "\"", "\\\"")
	return " \"" + title + "\""
}

func (c *converter) buildLink(content, href, title string) string {
	return "[" + content + "](" + c.processURL(href) + titlePart(title) + ")"
}

var paragraphSplitRE = regexp.MustCompile(`\n{2,}`)

func transformLinkContent(raw string) (string, bool, bool) {
	lead := strings.HasPrefix(raw, " ")
	trail := strings.HasSuffix(raw, " ")
	core := strings.Trim(raw, " \n")
	if core == "" {
		return "", lead, trail
	}
	parts := paragraphSplitRE.Split(core, -1)
	for i, p := range parts {
		parts[i] = strings.Trim(p, " \n")
	}
	var nonEmpty []string
	for _, p := range parts {
		if p != "" {
			nonEmpty = append(nonEmpty, p)
		}
	}
	return strings.Join(nonEmpty, "  \n\\\n"), lead, trail
}

func (c *converter) renderLink(n *html.Node, ctx rctx) frag {
	if ctx.code {
		return frag{s: c.extractText(n), kind: fragInline, node: n}
	}
	href, _ := getAttr(n, "href")
	title, _ := getAttr(n, "title")

	// A lone heading child bubbles out of the link.
	{
		eff := effectiveChildren(n)
		if len(eff) == 1 && eff[0].Type == html.ElementNode {
			tag := tagName(eff[0])
			if len(tag) == 2 && tag[0] == 'h' && tag[1] >= '1' && tag[1] <= '6' {
				heading := eff[0]
				childCtx := ctx.forWrapper("[")
				childCtx.link = true
				childCtx.heading = true
				child := c.renderChildren(heading, childCtx)
				content, _, _ := transformLinkContent(child.s)
				content = flattenHeadingText(content)
				if content != "" || true {
					link := c.buildLink(content, href, title)
					if strings.TrimSpace(content) == "" && false {
						return frag{kind: fragEmpty, node: n}
					}
					return frag{s: strings.Repeat("#", int(tag[1]-'0')) + " " + link, kind: fragBlock, node: n}
				}
			}
		}
	}

	childCtx := ctx.forWrapper("[")
	childCtx.link = true
	childCtx.linkWrapDelim = ""
	child := c.renderChildren(n, childCtx)
	content, lead, trail := transformLinkContent(child.s)
	if ctx.linkWrapDelim != "" && content != "" {
		content = wrapDelimitedText(content, ctx.linkWrapDelim, true)
	}
	link := c.buildLink(content, href, title)
	s := link
	if lead {
		s = " " + s
	}
	if trail {
		s += " "
	}
	return frag{s: s, kind: fragInline, node: n}
}

func escapeAltBrackets(alt string) string {
	alt = strings.NewReplacer("\r\n", " ", "\n", " ", "\r", " ").Replace(alt)
	var b strings.Builder
	prev := rune(0)
	first := true
	for _, r := range alt {
		if (r == '[' || r == ']') && (first || prev != '\\') {
			b.WriteByte('\\')
		}
		b.WriteRune(r)
		prev = r
		first = false
	}
	return b.String()
}

func (c *converter) renderImage(n *html.Node, ctx rctx) frag {
	src, _ := getAttr(n, "src")
	if strings.TrimSpace(src) == "" {
		return frag{kind: fragEmpty, node: n}
	}
	if ctx.code {
		return frag{kind: fragEmpty, node: n}
	}
	alt, _ := getAttr(n, "alt")
	title, _ := getAttr(n, "title")
	s := "![" + escapeAltBrackets(alt) + "](" + c.processURL(src) + titlePart(title) + ")"
	return frag{s: s, kind: fragInline, node: n}
}

// ---------- code and pre ----------

func (c *converter) extractText(n *html.Node) string {
	var b strings.Builder
	for ch := n.FirstChild; ch != nil; ch = ch.NextSibling {
		b.WriteString(c.extractTextNode(ch))
	}
	return b.String()
}

func (c *converter) extractTextNode(n *html.Node) string {
	if c.isExcluded(n) {
		return ""
	}
	switch n.Type {
	case html.TextNode:
		return n.Data
	case html.CommentNode, html.DoctypeNode:
		return ""
	case html.ElementNode:
		tag := tagName(n)
		if ignoredTags[tag] {
			return ""
		}
		switch tag {
		case "br":
			return "\n"
		case "blockquote":
			return " \"" + c.extractText(n) + "\" "
		case "div":
			return "\n" + c.extractText(n)
		case "h1", "h2", "h3", "h4", "h5", "h6":
			return c.extractText(n) + "\n"
		}
		return c.extractText(n)
	default:
		return c.extractText(n)
	}
}

func maxBacktickRun(s string) int {
	max := 0
	cur := 0
	for i := 0; i < len(s); i++ {
		if s[i] == '`' {
			cur++
			if cur > max {
				max = cur
			}
		} else {
			cur = 0
		}
	}
	return max
}

func formatCodeSpan(raw string) (string, string) {
	collapsed := collapseASCIIWhitespace(raw)
	var content string
	if strings.Trim(collapsed, " ") == "" {
		if collapsed == "" {
			return "", ""
		}
		content = " "
	} else {
		content = strings.Trim(collapsed, " ")
	}
	fence := strings.Repeat("`", maxBacktickRun(content)+1)
	prefix, suffix := "", ""
	if strings.HasPrefix(content, "`") {
		prefix = " "
	}
	if strings.HasSuffix(content, "`") {
		suffix = " "
	}
	return fence + prefix + content + suffix + fence, collapsed
}

func (c *converter) renderCodeSpan(n *html.Node, ctx rctx) frag {
	raw := c.extractText(n)
	formatted, collapsed := formatCodeSpan(raw)
	if formatted == "" {
		return frag{kind: fragEmpty, node: n, mergeClass: "code", codeRaw: collapsed}
	}
	return frag{s: formatted, kind: fragInline, node: n, mergeClass: "code", codeRaw: collapsed}
}

func languageFromClass(class string) string {
	if class == "" {
		return ""
	}
	replacer := strings.NewReplacer("language-", "", "lang-", "")
	for _, token := range strings.Split(class, " ") {
		if token == "" {
			continue
		}
		if strings.Contains(token, "language-") || strings.Contains(token, "lang-") {
			lang := replacer.Replace(token)
			if lang != "" {
				return lang
			}
		}
	}
	return ""
}

func (c *converter) preLanguage(n *html.Node) string {
	if class, ok := getAttr(n, "class"); ok {
		if lang := languageFromClass(class); lang != "" {
			return lang
		}
	}
	code := findFirstElement(n, "code")
	if code != nil && code != n {
		if class, ok := getAttr(code, "class"); ok {
			return languageFromClass(class)
		}
	}
	return ""
}

func (c *converter) renderPre(n *html.Node, ctx rctx) frag {
	if ctx.code {
		return frag{s: c.extractText(n), kind: fragInline, node: n}
	}
	if ctx.inline {
		// Rendered as an inline code span.
		formatted, collapsed := formatCodeSpan(c.extractText(n))
		if formatted == "" {
			return frag{kind: fragEmpty, node: n}
		}
		return frag{s: formatted, kind: fragInline, node: n, mergeClass: "code", codeRaw: collapsed}
	}
	content := c.extractText(n)
	content = strings.TrimSuffix(content, "\n")
	fenceLen := maxBacktickRun(content) + 1
	if fenceLen < 3 {
		fenceLen = 3
	}
	fence := strings.Repeat("`", fenceLen)
	lang := c.preLanguage(n)
	var s string
	if ctx.tableCell && ctx.tablePreserve {
		s = fence + lang + "<br />" + content + "<br />" + fence
	} else {
		s = fence + lang + "\n" + content + "\n" + fence
	}
	return frag{s: s, kind: fragBlock, node: n}
}

// ---------- headings ----------

var headingSpaceRE = regexp.MustCompile(` +`)

func flattenHeadingText(s string) string {
	s = strings.ReplaceAll(s, "\n", " ")
	s = headingSpaceRE.ReplaceAllString(s, " ")
	return strings.Trim(s, " ")
}

func (c *converter) renderHeading(n *html.Node, ctx rctx, level int) frag {
	if ctx.code {
		return frag{s: c.extractText(n) + "\n", kind: fragInline, node: n}
	}
	prefix := strings.Repeat("#", level) + " "
	if ctx.inline {
		childCtx := ctx
		childCtx.heading = true
		childCtx.atLineStart = false
		childCtx.linePrefix = c.strongDelimiter
		child := c.renderChildren(n, childCtx)
		content := flattenHeadingText(strings.Trim(child.s, " \n"))
		if content == "" {
			return frag{kind: fragEmpty, node: n}
		}
		return frag{s: c.strongDelimiter + content + c.strongDelimiter + "  \n", kind: fragInline, node: n}
	}
	childCtx := ctx.forWrapper(prefix)
	childCtx.heading = true
	child := c.renderChildren(n, childCtx)
	content := flattenHeadingText(child.s)
	if content == "" {
		return frag{kind: fragEmpty, node: n}
	}
	return frag{s: prefix + content, kind: fragBlock, node: n}
}

// ---------- blockquote ----------

var fenceInLineRE = regexp.MustCompile("(`{3,})[^`]*$")

func fenceLengthInLine(line string) (int, bool) {
	m := fenceInLineRE.FindStringSubmatchIndex(line)
	if m == nil {
		return 0, false
	}
	// The text before the fence should only look like block
	// prefixes / list markers / indentation.
	before := line[:m[0]]
	for _, r := range before {
		if r == ' ' || r == '>' || r == '-' || r == '.' || (r >= '0' && r <= '9') {
			continue
		}
		return 0, false
	}
	return m[3] - m[2], true
}

func isClosingFenceLine(line string, fenceLen int) bool {
	// Strip common block prefixes repeatedly.
	s := line
	for {
		s = strings.TrimLeft(s, " ")
		if strings.HasPrefix(s, "> ") {
			s = s[2:]
			continue
		}
		if strings.HasPrefix(s, "- ") {
			s = s[2:]
			continue
		}
		break
	}
	s = strings.TrimSpace(s)
	if s == "" {
		return false
	}
	for _, r := range s {
		if r != '`' {
			return false
		}
	}
	return utf8.RuneCountInString(s) == fenceLen
}

func (c *converter) renderBlockquote(n *html.Node, ctx rctx) frag {
	if ctx.code {
		return frag{s: " \"" + c.extractText(n) + "\" ", kind: fragInline, node: n}
	}
	if ctx.inline {
		child := c.renderChildren(n, ctx)
		content := strings.Trim(child.s, " \n")
		return frag{s: " \"" + content + "\" ", kind: fragInline, node: n}
	}
	childCtx := ctx.forBlock()
	childCtx.blockquote = true
	child := c.renderChildren(n, childCtx)
	content := trimBlockString(child.s)
	if content == "" {
		return frag{kind: fragEmpty, node: n}
	}
	lines := strings.Split(content, "\n")
	inFence := false
	fenceLen := 0
	firstContent := false
	for i, line := range lines {
		if !inFence {
			if fl, ok := fenceLengthInLine(line); ok {
				inFence = true
				fenceLen = fl
				firstContent = true
				lines[i] = "> " + line
				continue
			}
			lines[i] = "> " + line
			continue
		}
		// Inside a fenced code block.
		if isClosingFenceLine(line, fenceLen) {
			inFence = false
			lines[i] = "> " + line
			continue
		}
		if firstContent {
			firstContent = false
			lines[i] = "> " + line
			continue
		}
		// Subsequent raw code lines are not prefixed.
		lines[i] = line
	}
	return frag{s: strings.Join(lines, "\n"), kind: fragBlock, node: n}
}

// ---------- lists ----------

func (c *converter) renderList(n *html.Node, ctx rctx) frag {
	if ctx.code {
		return frag{s: c.extractText(n), kind: fragInline, node: n}
	}
	if ctx.inline {
		f := c.renderChildren(n, ctx)
		f.node = n
		return f
	}
	ordered := tagName(n) == "ol"
	start := 1
	if ordered {
		if v, ok := getAttr(n, "start"); ok {
			if parsed, err := strconv.Atoi(v); err == nil {
				start = parsed
			}
		}
	}

	// Group child nodes into items.
	type item struct{ nodes []*html.Node }
	var items []item
	var cur *item
	flushGroup := func() {
		if cur != nil {
			items = append(items, *cur)
			cur = nil
		}
	}
	for _, ch := range childNodes(n) {
		if ch.Type == html.ElementNode && tagName(ch) == "li" {
			flushGroup()
			cur = &item{}
			cur.nodes = append(cur.nodes, childNodes(ch)...)
		} else {
			if cur == nil {
				cur = &item{}
			}
			cur.nodes = append(cur.nodes, ch)
		}
	}
	flushGroup()

	childCtxBase := ctx.forBlock()
	var rendered []string
	for _, it := range items {
		f := c.renderNodeList(it.nodes, childCtxBase)
		content := trimBlockString(f.s)
		if content == "" {
			continue
		}
		rendered = append(rendered, content)
	}
	if len(rendered) == 0 {
		return frag{kind: fragEmpty, node: n}
	}

	lastNum := start + len(rendered) - 1
	width := len(strconv.Itoa(lastNum))
	var lines []string
	for i, content := range rendered {
		var marker string
		if ordered {
			marker = formatOrderedMarker(start+i, width)
		} else {
			marker = "- "
		}
		indent := strings.Repeat(" ", len(marker))
		cl := strings.Split(content, "\n")
		for j, line := range cl {
			if j == 0 {
				lines = append(lines, marker+line)
			} else {
				lines = append(lines, indent+line)
			}
		}
	}
	return frag{s: strings.Join(lines, "\n"), kind: fragBlock, node: n}
}

func formatOrderedMarker(num, width int) string {
	// Equivalent to fmt.Sprintf("%0*d. ", width, num).
	s := strconv.Itoa(num)
	if len(s) < width {
		if strings.HasPrefix(s, "-") {
			// Zero padding goes after the sign.
			s = "-" + strings.Repeat("0", width-len(s)) + s[1:]
		} else {
			s = strings.Repeat("0", width-len(s)) + s
		}
	}
	return s + ". "
}
GO
"}

