package main

import (
	"regexp"
	"strconv"
	"strings"
	"unicode/utf8"

	"golang.org/x/net/html"
)

func (c *converter) renderNode(n *html.Node, ctx rctx) frag {
	if n == nil {
		return frag{kind: fragEmpty}
	}
	if c.isExcluded(n) {
		return frag{kind: fragEmpty, node: n}
	}
	if ctx.visit && c.visited != nil {
		if c.visited[n] {
			return frag{kind: fragEmpty, node: n}
		}
		c.visited[n] = true
	}

	switch n.Type {
	case html.TextNode:
		if ctx.code {
			return frag{s: collapseASCIIWhitespace(n.Data), kind: fragInline, node: n}
		}
		s := c.escapeText(n, collapseASCIIWhitespace(n.Data), ctx)
		if s == "" {
			return frag{kind: fragEmpty, node: n}
		}
		return frag{s: s, kind: fragInline, node: n}
	case html.CommentNode, html.DoctypeNode:
		return frag{kind: fragEmpty, node: n}
	case html.DocumentNode:
		body := findFirstElement(n, "body")
		if body == nil {
			return frag{kind: fragEmpty, node: n}
		}
		return c.renderNode(body, ctx)
	case html.ElementNode:
		// handled below
	default:
		return frag{kind: fragEmpty, node: n}
	}

	tag := tagName(n)
	if ignoredTags[tag] {
		return frag{kind: fragEmpty, node: n}
	}

	switch tag {
	case "html":
		body := findFirstElement(n, "body")
		if body == nil {
			return frag{kind: fragEmpty, node: n}
		}
		return c.renderNode(body, ctx)
	case "head":
		return frag{kind: fragEmpty, node: n}
	case "body":
		return c.renderChildren(n, ctx.forBlock())
	case "br":
		return frag{s: "  \n", kind: fragBreak, node: n}
	case "hr":
		if ctx.code {
			return frag{kind: fragEmpty, node: n}
		}
		if ctx.inline {
			return frag{kind: fragEmpty, node: n}
		}
		return frag{s: "* * *", kind: fragBlock, node: n}
	case "img", "image":
		return c.renderImage(n, ctx)
	case "a":
		return c.renderLink(n, ctx)
	case "strong", "b":
		if ctx.code {
			return frag{s: c.extractText(n), kind: fragInline, node: n}
		}
		if ctx.strong {
			f := c.renderChildren(n, ctx)
			f.node = n
			return f
		}
		return c.renderEmphasis(n, ctx, c.strongDelimiter, true)
	case "em", "i":
		if ctx.code {
			return frag{s: c.extractText(n), kind: fragInline, node: n}
		}
		if ctx.em {
			f := c.renderChildren(n, ctx)
			f.node = n
			return f
		}
		return c.renderEmphasis(n, ctx, "*", false)
	case "del", "s", "strike":
		if c.pluginStrikethrough {
			if ctx.strike {
				f := c.renderChildren(n, ctx)
				f.node = n
				return f
			}
			childCtx := ctx.forWrapper("~~")
			childCtx.strike = true
			child := c.renderChildren(n, childCtx)
			return wrapInlineFrag(child, "~~", n, "strike")
		}
		f := c.renderChildren(n, ctx)
		f.node = n
		return f
	case "code", "kbd", "samp", "var", "tt":
		return c.renderCodeSpan(n, ctx)
	case "pre":
		return c.renderPre(n, ctx)
	case "h1", "h2", "h3", "h4", "h5", "h6":
		return c.renderHeading(n, ctx, int(tag[1]-'0'))
	case "blockquote":
		return c.renderBlockquote(n, ctx)
	case "ul", "ol":
		return c.renderList(n, ctx)
	case "table":
		if c.pluginTable {
			return c.renderTable(n, ctx)
		}
		child := c.renderChildren(n, ctx.forBlock())
		if trimBlockString(child.s) == "" {
			return frag{kind: fragEmpty, node: n}
		}
		return frag{s: trimBlockString(child.s), kind: fragBlock, node: n}
	case "tr":
		if ctx.tableFallback {
			child := c.renderChildren(n, ctx)
			if trimBlockString(child.s) == "" {
				return frag{kind: fragEmpty, node: n}
			}
			return frag{s: trimBlockString(child.s), kind: fragBlock, node: n}
		}
		f := c.renderChildren(n, ctx)
		f.node = n
		return f
	case "p":
		childCtx := ctx.forBlock()
		childCtx.inline = true
		child := c.renderChildren(n, childCtx)
		if trimBlockString(child.s) == "" {
			return frag{kind: fragEmpty, node: n}
		}
		return frag{s: trimBlockString(child.s), kind: fragBlock, node: n}
	}

	if blockTags[tag] {
		child := c.renderChildren(n, ctx.forBlock())
		if trimBlockString(child.s) == "" {
			return frag{kind: fragEmpty, node: n}
		}
		return frag{s: trimBlockString(child.s), kind: fragBlock, node: n}
	}
	// Inline / unknown element: transparent.
	f := c.renderChildren(n, ctx)
	f.node = n
	// A transparent wrapper that produced a block keeps block kind;
	// an inline result keeps its spaces for wrapper handling.
	return f
}

// ---------- emphasis ----------

func wrapDelimitedLine(content, delim string) string {
	hardSuffix := ""
	if strings.HasSuffix(content, "  ") {
		hardSuffix = "  "
		content = strings.TrimSuffix(content, "  ")
	}
	lead := strings.HasPrefix(content, " ")
	trail := strings.HasSuffix(content, " ")
	trimmed := strings.Trim(content, " ")
	if trimmed == "" {
		return content + hardSuffix
	}
	out := ""
	if lead {
		out += " "
	}
	out += delim + trimmed + delim
	if trail && hardSuffix == "" {
		out += " "
	}
	out += hardSuffix
	return out
}

func wrapDelimitedText(s, delim string, skipBackslashLine bool) string {
	lines := strings.Split(s, "\n")
	for i, line := range lines {
		if strings.TrimSpace(line) == "" {
			continue
		}
		if skipBackslashLine && line == "\\" {
			continue
		}
		lines[i] = wrapDelimitedLine(line, delim)
	}
	return strings.Join(lines, "\n")
}

func wrapInlineFrag(child frag, delim string, node *html.Node, mergeClass string) frag {
	s := child.s
	if strings.TrimSpace(s) == "" {
		if strings.Contains(s, " ") {
			return frag{s: " ", kind: fragInline, node: node}
		}
		return frag{kind: fragEmpty, node: node}
	}
	if !strings.Contains(s, "\n") {
		lead := strings.HasPrefix(s, " ")
		trail := strings.HasSuffix(s, " ")
		inner := strings.Trim(s, " ")
		wrapped := delim + inner + delim
		out := wrapped
		if lead {
			out = " " + out
		}
		if trail {
			out += " "
		}
		var innerFrag *frag
		if child.sole != nil {
			innerFrag = child.sole
		} else {
			innerFrag = &frag{s: inner, kind: fragInline}
		}
		return frag{
			s: out, kind: fragInline, node: node, mergeClass: mergeClass,
			wrap: &wrapInfo{delim: delim, inner: inner, innerFrag: innerFrag, lead: lead, trail: trail},
		}
	}
	lead := strings.HasPrefix(s, " ")
	trail := strings.HasSuffix(s, " ")
	core := strings.Trim(s, " \n")
	wrapped := wrapDelimitedText(core, delim, false)
	out := wrapped
	if lead {
		out = " " + out
	}
	if trail {
		out += " "
	}
	kind := fragInline
	if strings.Contains(core, "\n\n") || child.kind == fragBlock {
		kind = fragBlock
	}
	return frag{s: out, kind: kind, node: node, mergeClass: mergeClass}
}

func (c *converter) renderEmphasis(n *html.Node, ctx rctx, delim string, isStrong bool) frag {
	// A lone link child gets the emphasis inside the link text.
	if !ctx.suppressLinkSpecial {
		eff := effectiveChildren(n)
		if len(eff) == 1 && eff[0].Type == html.ElementNode && tagName(eff[0]) == "a" {
			linkCtx := ctx
			linkCtx.linkWrapDelim = delim
			if isStrong {
				linkCtx.strong = true
			} else {
				linkCtx.em = true
			}
			f := c.renderNode(eff[0], linkCtx)
			// The wrapper's own leading/trailing whitespace was
			// trimmed by the link; a link fragment is inline.
			return f
		}
	}
	childCtx := ctx.forWrapper(delim)
	if isStrong {
		childCtx.strong = true
	} else {
		childCtx.em = true
	}
	child := c.renderChildren(n, childCtx)
	return wrapInlineFrag(child, delim, n, "emphasis")
}

// ---------- links and images ----------

func titlePart(title string) string {
	if title == "" {
		return ""
	}
	title = strings.NewReplacer("\r\n", " ", "\n", " ", "\r", " ").Replace(title)
	if strings.Contains(title, "\"") && !strings.Contains(title, "'") {
		return " '" + title + "'"
	}
	title = strings.ReplaceAll(title, "\"", "\\\"")
	return " \"" + title + "\""
}

func (c *converter) buildLink(content, href, title string) string {
	return "[" + content + "](" + c.processURL(href) + titlePart(title) + ")"
}

var paragraphSplitRE = regexp.MustCompile(`\n{2,}`)

func transformLinkContent(raw string) (string, bool, bool) {
	lead := strings.HasPrefix(raw, " ")
	trail := strings.HasSuffix(raw, " ")
	core := strings.Trim(raw, " \n")
	if core == "" {
		return "", lead, trail
	}
	parts := paragraphSplitRE.Split(core, -1)
	for i, p := range parts {
		parts[i] = strings.Trim(p, " \n")
	}
	var nonEmpty []string
	for _, p := range parts {
		if p != "" {
			nonEmpty = append(nonEmpty, p)
		}
	}
	return strings.Join(nonEmpty, "  \n\\\n"), lead, trail
}

func (c *converter) renderLink(n *html.Node, ctx rctx) frag {
	if ctx.code {
		return frag{s: c.extractText(n), kind: fragInline, node: n}
	}
	href, _ := getAttr(n, "href")
	title, _ := getAttr(n, "title")

	// A lone heading child bubbles out of the link.
	{
		eff := effectiveChildren(n)
		if len(eff) == 1 && eff[0].Type == html.ElementNode {
			tag := tagName(eff[0])
			if len(tag) == 2 && tag[0] == 'h' && tag[1] >= '1' && tag[1] <= '6' {
				heading := eff[0]
				childCtx := ctx.forWrapper("[")
				childCtx.link = true
				childCtx.heading = true
				child := c.renderChildren(heading, childCtx)
				content, _, _ := transformLinkContent(child.s)
				content = flattenHeadingText(content)
				if content != "" || true {
					link := c.buildLink(content, href, title)
					if strings.TrimSpace(content) == "" && false {
						return frag{kind: fragEmpty, node: n}
					}
					return frag{s: strings.Repeat("#", int(tag[1]-'0')) + " " + link, kind: fragBlock, node: n}
				}
			}
		}
	}

	childCtx := ctx.forWrapper("[")
	childCtx.link = true
	childCtx.linkWrapDelim = ""
	child := c.renderChildren(n, childCtx)
	content, lead, trail := transformLinkContent(child.s)
	if ctx.linkWrapDelim != "" && content != "" {
		content = wrapDelimitedText(content, ctx.linkWrapDelim, true)
	}
	link := c.buildLink(content, href, title)
	s := link
	if lead {
		s = " " + s
	}
	if trail {
		s += " "
	}
	return frag{s: s, kind: fragInline, node: n}
}

func escapeAltBrackets(alt string) string {
	alt = strings.NewReplacer("\r\n", " ", "\n", " ", "\r", " ").Replace(alt)
	var b strings.Builder
	prev := rune(0)
	first := true
	for _, r := range alt {
		if (r == '[' || r == ']') && (first || prev != '\\') {
			b.WriteByte('\\')
		}
		b.WriteRune(r)
		prev = r
		first = false
	}
	return b.String()
}

func (c *converter) renderImage(n *html.Node, ctx rctx) frag {
	src, _ := getAttr(n, "src")
	if strings.TrimSpace(src) == "" {
		return frag{kind: fragEmpty, node: n}
	}
	if ctx.code {
		return frag{kind: fragEmpty, node: n}
	}
	alt, _ := getAttr(n, "alt")
	title, _ := getAttr(n, "title")
	s := "![" + escapeAltBrackets(alt) + "](" + c.processURL(src) + titlePart(title) + ")"
	return frag{s: s, kind: fragInline, node: n}
}

// ---------- code and pre ----------

func (c *converter) extractText(n *html.Node) string {
	var b strings.Builder
	for ch := n.FirstChild; ch != nil; ch = ch.NextSibling {
		b.WriteString(c.extractTextNode(ch))
	}
	return b.String()
}

func (c *converter) extractTextNode(n *html.Node) string {
	if c.isExcluded(n) {
		return ""
	}
	switch n.Type {
	case html.TextNode:
		return n.Data
	case html.CommentNode, html.DoctypeNode:
		return ""
	case html.ElementNode:
		tag := tagName(n)
		if ignoredTags[tag] {
			return ""
		}
		switch tag {
		case "br":
			return "\n"
		case "blockquote":
			return " \"" + c.extractText(n) + "\" "
		case "div":
			return "\n" + c.extractText(n)
		case "h1", "h2", "h3", "h4", "h5", "h6":
			return c.extractText(n) + "\n"
		}
		return c.extractText(n)
	default:
		return c.extractText(n)
	}
}

func maxBacktickRun(s string) int {
	max := 0
	cur := 0
	for i := 0; i < len(s); i++ {
		if s[i] == '`' {
			cur++
			if cur > max {
				max = cur
			}
		} else {
			cur = 0
		}
	}
	return max
}

func formatCodeSpan(raw string) (string, string) {
	collapsed := collapseASCIIWhitespace(raw)
	var content string
	if strings.Trim(collapsed, " ") == "" {
		if collapsed == "" {
			return "", ""
		}
		content = " "
	} else {
		content = strings.Trim(collapsed, " ")
	}
	fence := strings.Repeat("`", maxBacktickRun(content)+1)
	prefix, suffix := "", ""
	if strings.HasPrefix(content, "`") {
		prefix = " "
	}
	if strings.HasSuffix(content, "`") {
		suffix = " "
	}
	return fence + prefix + content + suffix + fence, collapsed
}

func (c *converter) renderCodeSpan(n *html.Node, ctx rctx) frag {
	raw := c.extractText(n)
	formatted, collapsed := formatCodeSpan(raw)
	if formatted == "" {
		return frag{kind: fragEmpty, node: n, mergeClass: "code", codeRaw: collapsed}
	}
	return frag{s: formatted, kind: fragInline, node: n, mergeClass: "code", codeRaw: collapsed}
}

func languageFromClass(class string) string {
	if class == "" {
		return ""
	}
	replacer := strings.NewReplacer("language-", "", "lang-", "")
	for _, token := range strings.Split(class, " ") {
		if token == "" {
			continue
		}
		if strings.Contains(token, "language-") || strings.Contains(token, "lang-") {
			lang := replacer.Replace(token)
			if lang != "" {
				return lang
			}
		}
	}
	return ""
}

func (c *converter) preLanguage(n *html.Node) string {
	if class, ok := getAttr(n, "class"); ok {
		if lang := languageFromClass(class); lang != "" {
			return lang
		}
	}
	code := findFirstElement(n, "code")
	if code != nil && code != n {
		if class, ok := getAttr(code, "class"); ok {
			return languageFromClass(class)
		}
	}
	return ""
}

func (c *converter) renderPre(n *html.Node, ctx rctx) frag {
	if ctx.code {
		return frag{s: c.extractText(n), kind: fragInline, node: n}
	}
	if ctx.inline {
		// Rendered as an inline code span.
		formatted, collapsed := formatCodeSpan(c.extractText(n))
		if formatted == "" {
			return frag{kind: fragEmpty, node: n}
		}
		return frag{s: formatted, kind: fragInline, node: n, mergeClass: "code", codeRaw: collapsed}
	}
	content := c.extractText(n)
	content = strings.TrimSuffix(content, "\n")
	fenceLen := maxBacktickRun(content) + 1
	if fenceLen < 3 {
		fenceLen = 3
	}
	fence := strings.Repeat("`", fenceLen)
	lang := c.preLanguage(n)
	var s string
	if ctx.tableCell && ctx.tablePreserve {
		s = fence + lang + "<br />" + content + "<br />" + fence
	} else {
		s = fence + lang + "\n" + content + "\n" + fence
	}
	return frag{s: s, kind: fragBlock, node: n}
}

// ---------- headings ----------

var headingSpaceRE = regexp.MustCompile(` +`)

func flattenHeadingText(s string) string {
	s = strings.ReplaceAll(s, "\n", " ")
	s = headingSpaceRE.ReplaceAllString(s, " ")
	return strings.Trim(s, " ")
}

func (c *converter) renderHeading(n *html.Node, ctx rctx, level int) frag {
	if ctx.code {
		return frag{s: c.extractText(n) + "\n", kind: fragInline, node: n}
	}
	prefix := strings.Repeat("#", level) + " "
	if ctx.inline {
		childCtx := ctx
		childCtx.heading = true
		childCtx.atLineStart = false
		childCtx.linePrefix = c.strongDelimiter
		child := c.renderChildren(n, childCtx)
		content := flattenHeadingText(strings.Trim(child.s, " \n"))
		if content == "" {
			return frag{kind: fragEmpty, node: n}
		}
		return frag{s: c.strongDelimiter + content + c.strongDelimiter + "  \n", kind: fragInline, node: n}
	}
	childCtx := ctx.forWrapper(prefix)
	childCtx.heading = true
	child := c.renderChildren(n, childCtx)
	content := flattenHeadingText(child.s)
	if content == "" {
		return frag{kind: fragEmpty, node: n}
	}
	return frag{s: prefix + content, kind: fragBlock, node: n}
}

// ---------- blockquote ----------

var fenceInLineRE = regexp.MustCompile("(`{3,})[^`]*$")

func fenceLengthInLine(line string) (int, bool) {
	m := fenceInLineRE.FindStringSubmatchIndex(line)
	if m == nil {
		return 0, false
	}
	// The text before the fence should only look like block
	// prefixes / list markers / indentation.
	before := line[:m[0]]
	for _, r := range before {
		if r == ' ' || r == '>' || r == '-' || r == '.' || (r >= '0' && r <= '9') {
			continue
		}
		return 0, false
	}
	return m[3] - m[2], true
}

func isClosingFenceLine(line string, fenceLen int) bool {
	// Strip common block prefixes repeatedly.
	s := line
	for {
		s = strings.TrimLeft(s, " ")
		if strings.HasPrefix(s, "> ") {
			s = s[2:]
			continue
		}
		if strings.HasPrefix(s, "- ") {
			s = s[2:]
			continue
		}
		break
	}
	s = strings.TrimSpace(s)
	if s == "" {
		return false
	}
	for _, r := range s {
		if r != '`' {
			return false
		}
	}
	return utf8.RuneCountInString(s) == fenceLen
}

func (c *converter) renderBlockquote(n *html.Node, ctx rctx) frag {
	if ctx.code {
		return frag{s: " \"" + c.extractText(n) + "\" ", kind: fragInline, node: n}
	}
	if ctx.inline {
		child := c.renderChildren(n, ctx)
		content := strings.Trim(child.s, " \n")
		return frag{s: " \"" + content + "\" ", kind: fragInline, node: n}
	}
	childCtx := ctx.forBlock()
	childCtx.blockquote = true
	child := c.renderChildren(n, childCtx)
	content := trimBlockString(child.s)
	if content == "" {
		return frag{kind: fragEmpty, node: n}
	}
	lines := strings.Split(content, "\n")
	inFence := false
	fenceLen := 0
	firstContent := false
	for i, line := range lines {
		if !inFence {
			if fl, ok := fenceLengthInLine(line); ok {
				inFence = true
				fenceLen = fl
				firstContent = true
				lines[i] = "> " + line
				continue
			}
			lines[i] = "> " + line
			continue
		}
		// Inside a fenced code block.
		if isClosingFenceLine(line, fenceLen) {
			inFence = false
			lines[i] = "> " + line
			continue
		}
		if firstContent {
			firstContent = false
			lines[i] = "> " + line
			continue
		}
		// Subsequent raw code lines are not prefixed.
		lines[i] = line
	}
	return frag{s: strings.Join(lines, "\n"), kind: fragBlock, node: n}
}

// ---------- lists ----------

func (c *converter) renderList(n *html.Node, ctx rctx) frag {
	if ctx.code {
		return frag{s: c.extractText(n), kind: fragInline, node: n}
	}
	if ctx.inline {
		f := c.renderChildren(n, ctx)
		f.node = n
		return f
	}
	ordered := tagName(n) == "ol"
	start := 1
	if ordered {
		if v, ok := getAttr(n, "start"); ok {
			if parsed, err := strconv.Atoi(v); err == nil {
				start = parsed
			}
		}
	}

	// Group child nodes into items.
	type item struct{ nodes []*html.Node }
	var items []item
	var cur *item
	flushGroup := func() {
		if cur != nil {
			items = append(items, *cur)
			cur = nil
		}
	}
	for _, ch := range childNodes(n) {
		if ch.Type == html.ElementNode && tagName(ch) == "li" {
			flushGroup()
			cur = &item{}
			cur.nodes = append(cur.nodes, childNodes(ch)...)
		} else {
			if cur == nil {
				cur = &item{}
			}
			cur.nodes = append(cur.nodes, ch)
		}
	}
	flushGroup()

	childCtxBase := ctx.forBlock()
	var rendered []string
	for _, it := range items {
		f := c.renderNodeList(it.nodes, childCtxBase)
		content := trimBlockString(f.s)
		if content == "" {
			continue
		}
		rendered = append(rendered, content)
	}
	if len(rendered) == 0 {
		return frag{kind: fragEmpty, node: n}
	}

	lastNum := start + len(rendered) - 1
	width := len(strconv.Itoa(lastNum))
	var lines []string
	for i, content := range rendered {
		var marker string
		if ordered {
			marker = formatOrderedMarker(start+i, width)
		} else {
			marker = "- "
		}
		indent := strings.Repeat(" ", len(marker))
		cl := strings.Split(content, "\n")
		for j, line := range cl {
			if j == 0 {
				lines = append(lines, marker+line)
			} else {
				lines = append(lines, indent+line)
			}
		}
	}
	return frag{s: strings.Join(lines, "\n"), kind: fragBlock, node: n}
}

func formatOrderedMarker(num, width int) string {
	// Equivalent to fmt.Sprintf("%0*d. ", width, num).
	s := strconv.Itoa(num)
	if len(s) < width {
		if strings.HasPrefix(s, "-") {
			// Zero padding goes after the sign.
			s = "-" + strings.Repeat("0", width-len(s)) + s[1:]
		} else {
			s = strings.Repeat("0", width-len(s)) + s
		}
	}
	return s + ". "
}
GO
"}

{"command":"cat > url.go <<'GO'
package main

import (
	"net/url"
	"strings"
)

var urlFallbackReplacer = strings.NewReplacer(
	" ", "%20",
	"(", "%28",
	")", "%29",
	"[", "%5B",
	"]", "%5D",
	"<", "%3C",
	">", "%3E",
)

func parseDomain(domain string) *url.URL {
	if domain == "" {
		return nil
	}
	u, err := url.Parse(domain)
	if err == nil && u.Host != "" {
		return u
	}
	u2, err2 := url.Parse("http://" + domain)
	if err2 != nil || u2.Host == "" {
		return nil
	}
	return u2
}

func reencodeRawQuery(raw string) string {
	parts := strings.Split(raw, "&")
	for i, part := range parts {
		if part == "" {
			continue
		}
		key, val, hasEq := strings.Cut(part, "=")
		decKey, err := url.QueryUnescape(key)
		if err != nil {
			continue
		}
		encKey := strings.ReplaceAll(url.QueryEscape(decKey), "+", "%20")
		if !hasEq {
			parts[i] = encKey
			continue
		}
		decVal, err := url.QueryUnescape(val)
		if err != nil {
			continue
		}
		encVal := strings.ReplaceAll(url.QueryEscape(decVal), "+", "%20")
		parts[i] = encKey + "=" + encVal
	}
	return strings.Join(parts, "&")
}

func (c *converter) processURL(raw string) string {
	raw = strings.TrimSpace(raw)
	if raw == "" && c.domain == "" {
		return ""
	}
	base := parseDomain(c.domain)
	u, err := url.Parse(raw)
	if err != nil {
		return urlFallbackReplacer.Replace(raw)
	}
	if base != nil {
		u = base.ResolveReference(u)
	}
	if u.RawQuery != "" {
		u.RawQuery = reencodeRawQuery(u.RawQuery)
	}
	return urlFallbackReplacer.Replace(u.String())
}
GO
"}

