{"command":"cat > table.go <<'GO'
package main

import (
	"strconv"
	"strings"
	"unicode/utf8"

	"golang.org/x/net/html"
)

type tableCellData struct {
	content string
	align   string
	colspan int
	rowspan int
	isTH    bool
	node    *html.Node
}

type tableRowData struct {
	node    *html.Node
	cells   []*tableCellData
	inThead bool
}

func cellHasDescendantTag(n *html.Node, tags map[string]bool) bool {
	found := false
	var rec func(*html.Node)
	rec = func(x *html.Node) {
		for ch := x.FirstChild; ch != nil && !found; ch = ch.NextSibling {
			if ch.Type == html.ElementNode {
				if tags[tagName(ch)] {
					found = true
					return
				}
				rec(ch)
			}
		}
	}
	rec(n)
	return found
}

var tableHardSkipTags = map[string]bool{
	"blockquote": true, "h1": true, "h2": true, "h3": true, "h4": true,
	"h5": true, "h6": true, "hr": true, "ul": true, "ol": true,
	"table": true,
}

// renderTableCellContents renders one cell. In preserve mode block
// boundaries become <br /> runs, matching the observed rules: a boundary
// between two block-originated segments becomes four, any other blank-line
// boundary becomes two, and hard breaks become a single "  <br />".
func (c *converter) renderTableCellContents(cell *html.Node, ctx rctx) string {
	f := c.renderChildren(cell, ctx)
	content := trimBlockString(f.s)
	if !ctx.tablePreserve {
		return content
	}
	return preserveTableContent(content)
}

func preserveTableContent(content string) string {
	// Split into segments at blank lines, converting each separator.
	// We can no longer tell block origins from the flattened string,
	// so segment kinds are recovered by re-deriving them in the
	// dedicated preserve renderer below; this path is a fallback.
	if content == "" {
		return ""
	}
	parts := paragraphSplitRE.Split(content, -1)
	for i, p := range parts {
		parts[i] = strings.ReplaceAll(strings.Trim(p, " \n"), "  \n", "  <br />")
	}
	return strings.Join(parts, "<br /><br />")
}

func (c *converter) renderTable(table *html.Node, ctx rctx) frag {
	// Presentation tables fall back unless explicitly enabled.
	if role, ok := getAttr(table, "role"); ok && role == "presentation" && !c.tablePresentation {
		return c.renderTableFallback(table, ctx)
	}

	// Collect rows in document order, ignoring nested tables.
	var rowNodes []*html.Node
	var theadRows = make(map[*html.Node]bool)
	var caption *html.Node
	var collect func(n *html.Node, inThead bool)
	collect = func(n *html.Node, inThead bool) {
		for ch := n.FirstChild; ch != nil; ch = ch.NextSibling {
			if ch.Type != html.ElementNode {
				continue
			}
			tag := tagName(ch)
			if tag == "table" {
				continue
			}
			if tag == "caption" && caption == nil {
				caption = ch
				continue
			}
			childInThead := inThead || tag == "thead"
			if tag == "tr" {
				rowNodes = append(rowNodes, ch)
				if childInThead {
					theadRows[ch] = true
				}
				continue
			}
			collect(ch, childInThead)
		}
	}
	collect(table, false)

	// Caption rendered after the table (or alone if there is none).
	captionText := ""
	if caption != nil && !c.isExcluded(caption) {
		capCtx := ctx.forBlock()
		capCtx.tableCell = false
		capCtx.visit = false
		f := c.renderChildren(caption, capCtx)
		captionText = trimBlockString(f.s)
	}

	if len(rowNodes) == 0 {
		if captionText != "" {
			return frag{s: captionText, kind: fragBlock, node: table}
		}
		return frag{kind: fragEmpty, node: table}
	}

	// Build row data and render cells.
	preserve := c.tableNewline == "preserve"
	rows := make([]*tableRowData, 0, len(rowNodes))
	for _, tr := range rowNodes {
		if c.isExcluded(tr) {
			continue
		}
		row := &tableRowData{node: tr, inThead: theadRows[tr]}
		for _, cell := range childNodes(tr) {
			if cell.Type != html.ElementNode {
				continue
			}
			tag := tagName(cell)
			if tag != "td" && tag != "th" {
				continue
			}
			if c.isExcluded(cell) {
				continue
			}
			if cellHasDescendantTag(cell, tableHardSkipTags) {
				return c.renderTableFallback(table, ctx)
			}
			data := &tableCellData{node: cell, isTH: tag == "th", colspan: 1, rowspan: 1}
			if v, ok := getAttr(cell, "align"); ok {
				if v == "left" || v == "center" || v == "right" {
					data.align = v
				}
			}
			if v, ok := getAttr(cell, "colspan"); ok {
				if parsed, err := strconv.Atoi(v); err == nil && parsed >= 1 {
					data.colspan = parsed
				}
			}
			if v, ok := getAttr(cell, "rowspan"); ok {
				if parsed, err := strconv.Atoi(v); err == nil && parsed >= 1 {
					data.rowspan = parsed
				}
			}
			cellCtx := ctx.forBlock()
			cellCtx.tableCell = true
			cellCtx.tablePreserve = preserve
			cellCtx.visit = false
			data.content = c.renderPreservingCell(cell, cellCtx, preserve)
			row.cells = append(row.cells, data)
		}
		rows = append(rows, row)
	}

	if !preserve {
		for _, row := range rows {
			for _, cell := range row.cells {
				if strings.Contains(cell.content, "\n") {
					return c.renderTableFallback(table, ctx)
				}
			}
		}
	}

	if c.tableSkipEmpty {
		filtered := rows[:0]
		// Rebuild to avoid aliasing confusion.
		filtered = nil
		for _, row := range rows {
			empty := len(row.cells) == 0
			if !empty {
				empty = true
				for _, cell := range row.cells {
					if strings.TrimSpace(cell.content) != "" {
						empty = false
						break
					}
				}
			}
			if !empty {
				filtered = append(filtered, row)
			}
		}
		rows = filtered
		if len(rows) == 0 {
			if captionText != "" {
				return frag{s: captionText, kind: fragBlock, node: table}
			}
			return frag{kind: fragEmpty, node: table}
		}
	}

	// If there are no cells at all, the table disappears.
	totalCells := 0
	for _, r := range rows {
		totalCells += len(r.cells)
	}
	if totalCells == 0 {
		if captionText != "" {
			return frag{s: captionText, kind: fragBlock, node: table}
		}
		return frag{kind: fragEmpty, node: table}
	}

	// Expand rows into a grid, inserting rowspan placeholders.
	type gridCell struct {
		content string
		src     *tableCellData
		spanOf  *tableCellData
	}
	type activeSpan struct {
		col       int
		remaining int
		src       *tableCellData
	}
	spanContent := func(src *tableCellData) string {
		if c.tableSpan == "mirror" {
			return src.content
		}
		return ""
	}
	var grid [][]gridCell
	var actives []activeSpan
	insertActives := func(cur []gridCell) []gridCell {
		// Insert each active placeholder at its column, in
		// ascending column order.
		sorted := append([]activeSpan{}, actives...)
		for i := 0; i < len(sorted); i++ {
			for j := i + 1; j < len(sorted); j++ {
				if sorted[j].col < sorted[i].col {
					sorted[i], sorted[j] = sorted[j], sorted[i]
				}
			}
		}
		for _, a := range sorted {
			for len(cur) < a.col {
				cur = append(cur, gridCell{content: ""})
			}
			placeholder := gridCell{content: spanContent(a.src), src: a.src, spanOf: a.src}
			cur = append(cur, gridCell{})
			copy(cur[a.col+1:], cur[a.col:])
			cur[a.col] = placeholder
		}
		var next []activeSpan
		for _, a := range actives {
			a.remaining--
			if a.remaining > 0 {
				next = append(next, a)
			}
		}
		actives = next
		return cur
	}

	for _, row := range rows {
		var cur []gridCell
		for _, cell := range row.cells {
			cur = append(cur, gridCell{content: cell.content, src: cell})
			for k := 1; k < cell.colspan; k++ {
				cur = append(cur, gridCell{content: spanContent(cell), src: cell, spanOf: cell})
			}
		}
		cur = insertActives(cur)
		// Register new actives from this row's cells at their
		// final columns.
		for col, gc := range cur {
			if gc.src == nil || gc.spanOf != nil {
				// Span placeholders from colspan also carry
				// the source's rowspan: register them via
				// their spanOf, handled below.
				if gc.spanOf != nil && gc.spanOf.rowspan > 1 {
					// Only register once per source column set:
					// colspan placeholders each occupy their
					// own column, so register each.
					actives = append(actives, activeSpan{col: col, remaining: gc.spanOf.rowspan - 1, src: gc.spanOf})
				}
				continue
			}
			if gc.src.rowspan > 1 {
				actives = append(actives, activeSpan{col: col, remaining: gc.src.rowspan - 1, src: gc.src})
			}
		}
		// The loop above registers a colspan+rowspan primary via
		// src and its colspan placeholders via spanOf; however a
		// primary that was itself a placeholder in `cur` (spanOf
		// == its own cell for colspan extras) is handled.
		grid = append(grid, cur)
	}
	for len(actives) > 0 {
		var cur []gridCell
		cur = insertActives(cur)
		grid = append(grid, cur)
	}

	numCols := 0
	for _, r := range grid {
		if len(r) > numCols {
			numCols = len(r)
		}
	}
	for i := range grid {
		for len(grid[i]) < numCols {
			grid[i] = append(grid[i], gridCell{content: ""})
		}
	}

	// Header selection.
	headerIdx := -1
	var alignSource *tableRowData
	for i, row := range rows {
		if row.inThead && len(row.cells) > 0 {
			headerIdx = i
			break
		}
	}
	if headerIdx < 0 {
		for i, row := range rows {
			hasTH := false
			for _, cell := range row.cells {
				if cell.isTH {
					hasTH = true
					break
				}
			}
			if hasTH {
				headerIdx = i
				break
			}
		}
	}
	synthetic := false
	if headerIdx < 0 {
		if c.tableHeaderPromotion && len(rows) > 0 {
			headerIdx = 0
		} else {
			synthetic = true
		}
	}
	if synthetic {
		if len(rows) > 0 {
			alignSource = rows[0]
		}
	} else {
		alignSource = rows[headerIdx]
	}
	var alignments []string
	if alignSource != nil {
		for _, cell := range alignSource.cells {
			alignments = append(alignments, cell.align)
		}
	}

	var headerCells []string
	var bodyRows [][]string
	if synthetic {
		for i := 0; i < numCols; i++ {
			headerCells = append(headerCells, "")
		}
		for _, r := range grid {
			var row []string
			for _, gc := range r {
				row = append(row, gc.content)
			}
			bodyRows = append(bodyRows, row)
		}
	} else {
		for _, gc := range grid[headerIdx] {
			headerCells = append(headerCells, gc.content)
		}
		for i, r := range grid {
			if i == headerIdx {
				continue
			}
			var row []string
			for _, gc := range r {
				row = append(row, gc.content)
			}
			bodyRows = append(bodyRows, row)
		}
	}

	rendered := renderMarkdownTable(headerCells, bodyRows, alignments, c.tablePadding)
	if captionText != "" {
		rendered += "\n\n" + captionText
	}
	return frag{s: rendered, kind: fragBlock, node: table}
}

func renderMarkdownTable(header []string, body [][]string, alignments []string, padding string) string {
	numCols := len(header)
	widths := make([]int, numCols)
	for i := 0; i < numCols; i++ {
		widths[i] = 1
	}
	measure := func(row []string) {
		for i, cell := range row {
			if i >= numCols {
				break
			}
			if w := utf8.RuneCountInString(cell); w > widths[i] {
				widths[i] = w
			}
		}
	}
	measure(header)
	for _, r := range body {
		measure(r)
	}
	formatRow := func(row []string) string {
		var b strings.Builder
		b.WriteByte('|')
		for i := 0; i < numCols; i++ {
			cell := ""
			if i < len(row) {
				cell = row[i]
			}
			switch padding {
			case "none":
				b.WriteString(cell)
			case "minimal":
				b.WriteString(" " + cell + " ")
			default: // aligned
				pad := widths[i] - utf8.RuneCountInString(cell)
				b.WriteString(" " + cell + strings.Repeat(" ", pad) + " ")
			}
			b.WriteByte('|')
		}
		return b.String()
	}
	var sep strings.Builder
	sep.WriteByte('|')
	for i := 0; i < numCols; i++ {
		length := 3
		if padding == "aligned" {
			length = widths[i] + 2
			if length < 3 {
				length = 3
			}
		}
		segment := strings.Repeat("-", length)
		align := ""
		if i < len(alignments) {
			align = alignments[i]
		}
		switch align {
		case "left":
			segment = ":" + segment[1:]
		case "right":
			segment = segment[:len(segment)-1] + ":"
		case "center":
			segment = ":" + segment[1:len(segment)-1] + ":"
		}
		sep.WriteString(segment)
		sep.WriteByte('|')
	}
	lines := []string{formatRow(header), sep.String()}
	for _, r := range body {
		lines = append(lines, formatRow(r))
	}
	return strings.Join(lines, "\n")
}

func (c *converter) renderTableFallback(table *html.Node, ctx rctx) frag {
	childCtx := ctx.forBlock()
	childCtx.tableFallback = true
	child := c.renderChildren(table, childCtx)
	if trimBlockString(child.s) == "" {
		return frag{kind: fragEmpty, node: table}
	}
	return frag{s: trimBlockString(child.s), kind: fragBlock, node: table}
}

// renderPreservingCell renders a cell. In non-preserve mode it is just
// the trimmed rendered children. In preserve mode it converts block
// boundaries and hard breaks to <br /> using segment origins: the
// rendered children are split at blank lines and each separator is
// sized by whether the neighbouring segments came from block content.
// Because the flattened string loses origins, we approximate the
// four-<br /> rule by checking the cell's child structure: if a blank
// line boundary lies between two block-level children (possibly nested
// one level in generic containers) it becomes four, otherwise two.
func (c *converter) renderPreservingCell(cell *html.Node, ctx rctx, preserve bool) string {
	if !preserve {
		f := c.renderChildren(cell, ctx)
		return trimBlockString(f.s)
	}
	// Render each direct child separately so segment origins are known.
	type seg struct {
		text  string
		block bool
	}
	var segs []seg
	for _, ch := range childNodes(cell) {
		f := c.renderNode(ch, ctx)
		if f.kind == fragBreak {
			segs = append(segs, seg{text: "  <br />", block: false})
			continue
		}
		t := trimBlockString(f.s)
		if t == "" {
			continue
		}
		isBlock := f.kind == fragBlock || (ch.Type == html.ElementNode && blockTags[tagName(ch)])
		// Convert any internal blank-line boundaries within this
		// child's rendering: nested block boundaries inside a
		// generic block are block-to-block (four) when the child
		// itself is a block container, otherwise two. Hard
		// breaks become a single "  <br />".
		parts := paragraphSplitRE.Split(t, -1)
		for pi, p := range parts {
			pp := strings.ReplaceAll(strings.Trim(p, " \n"), "  \n", "  <br />")
			if pp == "" {
				continue
			}
			if pi > 0 {
				// Internal boundary of this child.
				segs = append(segs, seg{text: pp, block: isBlock})
			} else {
				segs = append(segs, seg{text: pp, block: isBlock})
			}
		}
	}
	if len(segs) == 0 {
		return ""
	}
	var b strings.Builder
	for i, s := range segs {
		if s.text == "  <br />" {
			b.WriteString(s.text)
			continue
		}
		if i > 0 {
			prev := segs[i-1]
			if prev.text == "  <br />" {
				// Hard break already written.
			} else if prev.block && s.block {
				b.WriteString("<br /><br /><br /><br />")
			} else {
				b.WriteString("<br /><br />")
			}
		}
		b.WriteString(s.text)
	}
	return b.String()
}
