func renderMarkdownTable(header []string, body [][]string, alignments []string, padding string) string {
	numCols := len(header)
	widths := make([]int, numCols)
	for i := 0; i < numCols; i++ {
		widths[i] = 1
	}
	measure := func(row []string) {
		for i, cell := range row {
			if i >= numCols {
				break
			}
			if w := utf8.RuneCountInString(cell); w > widths[i] {
				widths[i] = w
			}
		}
	}
	measure(header)
	for _, r := range body {
		measure(r)
	}
	formatRow := func(row []string) string {
		var b strings.Builder
		b.WriteByte('|')
		for i := 0; i < numCols; i++ {
			cell := ""
			if i < len(row) {
				cell = row[i]
			}
			switch padding {
			case "none":
				b.WriteString(cell)
			case "minimal":
				b.WriteString(" " + cell + " ")
			default: // aligned
				pad := widths[i] - utf8.RuneCountInString(cell)
				b.WriteString(" " + cell + strings.Repeat(" ", pad) + " ")
			}
			b.WriteByte('|')
		}
		return b.String()
	}
	var sep strings.Builder
	sep.WriteByte('|')
	for i := 0; i < numCols; i++ {
		length := 3
		if padding == "aligned" {
			length = widths[i] + 2
			if length < 3 {
				length = 3
			}
		}
		segment := strings.Repeat("-", length)
		align := ""
		if i < len(alignments) {
			align = alignments[i]
		}
		switch align {
		case "left":
			segment = ":" + segment[1:]
		case "right":
			segment = segment[:len(segment)-1] + ":"
		case "center":
			segment = ":" + segment[1:len(segment)-1] + ":"
		}
		sep.WriteString(segment)
		sep.WriteByte('|')
	}
	lines := []string{formatRow(header), sep.String()}
	for _, r := range body {
		lines = append(lines, formatRow(r))
	}
	return strings.Join(lines, "\n")
}

func (c *converter) renderTableFallback(table *html.Node, ctx rctx) frag {
	childCtx := ctx.forBlock()
	childCtx.tableFallback = true
	child := c.renderChildren(table, childCtx)
	if trimBlockString(child.s) == "" {
		return frag{kind: fragEmpty, node: table}
	}
	return frag{s: trimBlockString(child.s), kind: fragBlock, node: table}
}

// renderPreservingCell renders a cell. In non-preserve mode it is just
// the trimmed rendered children. In preserve mode it converts block
// boundaries and hard breaks to <br /> using segment origins: the
// rendered children are split at blank lines and each separator is
// sized by whether the neighbouring segments came from block content.
// Because the flattened string loses origins, we approximate the
// four-<br /> rule by checking the cell's child structure: if a blank
// line boundary lies between two block-level children (possibly nested
// one level in generic containers) it becomes four, otherwise two.
func (c *converter) renderPreservingCell(cell *html.Node, ctx rctx, preserve bool) string {
	if !preserve {
		f := c.renderChildren(cell, ctx)
		return trimBlockString(f.s)
	}
	// Render each direct child separately so segment origins are known.
	type seg struct {
		text  string
		block bool
	}
	var segs []seg
	for _, ch := range childNodes(cell) {
		f := c.renderNode(ch, ctx)
		if f.kind == fragBreak {
			segs = append(segs, seg{text: "  <br />", block: false})
			continue
		}
		t := trimBlockString(f.s)
		if t == "" {
			continue
		}
		isBlock := f.kind == fragBlock || (ch.Type == html.ElementNode && blockTags[tagName(ch)])
		// Convert any internal blank-line boundaries within this
		// child's rendering: nested block boundaries inside a
		// generic block are block-to-block (four) when the child
		// itself is a block container, otherwise two. Hard
		// breaks become a single "  <br />".
		parts := paragraphSplitRE.Split(t, -1)
		for pi, p := range parts {
			pp := strings.ReplaceAll(strings.Trim(p, " \n"), "  \n", "  <br />")
			if pp == "" {
				continue
			}
			if pi > 0 {
				// Internal boundary of this child.
				segs = append(segs, seg{text: pp, block: isBlock})
			} else {
				segs = append(segs, seg{text: pp, block: isBlock})
			}
		}
	}
	if len(segs) == 0 {
		return ""
	}
	var b strings.Builder
	for i, s := range segs {
		if s.text == "  <br />" {
			b.WriteString(s.text)
			continue
		}
		if i > 0 {
			prev := segs[i-1]
			if prev.text == "  <br />" {
				// Hard break already written.
			} else if prev.block && s.block {
				b.WriteString("<br /><br /><br /><br />")
			} else {
				b.WriteString("<br /><br />")
			}
		}
		b.WriteString(s.text)
	}
	return b.String()
}
