		return trimBlockString(f.s)
	}
	type seg struct {
		text  string
		block bool
	}
	var segs []seg
	var inlineBuf string
	flushInline := func() {
		t := strings.TrimRight(inlineBuf, " ")
		t = strings.TrimSuffix(t, "  <br />")
		t = strings.TrimSpace(t)
		if t != "" {
			segs = append(segs, seg{text: t, block: false})
		}
		inlineBuf = ""
	}
	convertBreaks := func(s string) string {
		s = strings.ReplaceAll(s, "  \\n", "  <br />")
		s = strings.ReplaceAll(s, "\\n", "<br />")
		return s
	}
