			continue
		}
		if f.kind != fragBlock {
			inlineBuf = appendInline(inlineBuf, convertBreaks(f.s))
			continue
		}
		flushInline()
		t := trimBlockString(f.s)
		if t == "" {
			continue
		}
		isBlock := ch.Type == html.ElementNode && blockTags[tagName(ch)]
		parts := paragraphSplitRE.Split(t, -1)
		for _, p := range parts {
