	breakRun := 0
	for _, f := range frags {
		if f.kind == fragBreak {
			breakRun++
			if breakRun >= 2 {
				hasDoubleBreak = true
			}
			continue
		}
		if f.kind == fragEmpty || (f.kind == fragInline && strings.TrimSpace(f.s) == "") {
