	// list-separator logic below can see it.
	for _, f := range frags {
		if f.isList {
			hasBlock = true
		}
	}

	if !hasBlock && !hasDoubleBreak {
		var str string
		for _, f := range frags {
			if f.kind == fragBreak {
				str = strings.TrimRight(str, " ")
				if strings.TrimSpace(str) != "" {
					str += "  \\n"
				}
				continue
			}
			if f.kind == fragEmpty {
				continue
			}
			str = appendInline(str, f.s)
		}
		if strings.TrimSpace(str) == "" && !strings.Contains(str, " ") {
			return frag{kind: fragEmpty, sole: sole}
		}
		if strings.TrimSpace(str) == "" {
			str = " "
		}
		out := frag{s: str, kind: fragInline, sole: sole}
		if sole != nil {
			out.isList = sole.isList
			out.emptyLink = sole.emptyLink
		}
		return out
	}

	type joinedSeg struct {
		text   string
		isList bool
	}
	var segments []joinedSeg
	var cur string
	pendingBreaks := 0
	flush := func() {
		t := trimBlockString(cur)
		if t != "" {
			segments = append(segments, joinedSeg{text: t})
		}
		cur = ""
	}
	for _, f := range frags {
		if f.kind == fragBreak {
			pendingBreaks++
			continue
		}
		if f.kind == fragEmpty {
			if f.isList {
				flush()
				segments = append(segments, joinedSeg{text: "", isList: true})
			}
			continue
		}
		if f.kind == fragInline && strings.TrimSpace(f.s) == "" {
			if pendingBreaks == 0 && cur != "" {
				cur = appendInline(cur, " ")
			}
			continue
		}
		if f.kind == fragBlock {
			pendingBreaks = 0
			flush()
			segments = append(segments, joinedSeg{text: trimBlockString(f.s), isList: f.isList})
			continue
		}
		if pendingBreaks >= 2 {
			flush()
			cur = appendInline(cur, f.s)
		} else if pendingBreaks == 1 {
			if strings.TrimSpace(cur) != "" {
				cur = strings.TrimRight(cur, " ") + "  \\n" + strings.TrimLeft(f.s, " ")
			} else {
				cur = appendInline(cur, f.s)
			}
		} else {
			cur = appendInline(cur, f.s)
		}
		pendingBreaks = 0
	}
	flush()

	// Insert the list separator between consecutive list segments.
	var outSegs []string
	prevWasList := false
	listSegCount := 0
	nonListCount := 0
	for _, sg := range segments {
		if sg.isList {
			listSegCount++
			if prevWasList {
				outSegs = append(outSegs, "<!--THE END-->")
			}
			prevWasList = true
		} else if sg.text != "" {
			nonListCount++
			prevWasList = false
		}
		if sg.text != "" {
			outSegs = append(outSegs, sg.text)
		}
	}
	if len(outSegs) == 0 {
		kind := fragEmpty
		out := frag{kind: kind, sole: sole}
		if listSegCount > 0 {
			out.kind = fragBlock
			out.isList = true
		}
		return out
	}
	out := frag{s: strings.Join(outSegs, "\\n\\n"), kind: fragBlock, sole: sole}
	if listSegCount == 1 && nonListCount == 0 {
		// The whole sequence is a single list (ignoring any
		// separator, which only appears with 2+ lists).
		out.isList = true
	}
	if sole != nil {
		out.emptyLink = sole.emptyLink
		if sole.isList && len(segments) == 1 {
			out.isList = true
		}
	}
	return out
}

