fails=0; total=400
for i in range(total):
 rows=[]
 nrows=rng.randint(0,4)
 for r in range(nrows):
  cells=[]
  for c in range(rng.randint(0,4)):
   tag=rng.choice(['td','th'])
   attrs=""
   if rng.random()<0.2: attrs+=f" colspan='{rng.randint(0,3)}'"
   if rng.random()<0.2: attrs+=f" rowspan='{rng.randint(0,3)}'"
   if rng.random()<0.2: attrs+=f" align='{rng.choice(['left','center','right','CENTER','x'])}'"
   cells.append(f"<{tag}{attrs}>{rng.choice(cellcontents)}</{tag}>")
  rows.append("<tr>"+"".join(cells)+"</tr>")
 thead = f"<thead>{rows[0]}</thead>" if rows and rng.random()<0.4 else ""
 bodyrows = rows[1:] if thead else rows
 caption="<caption>cap</caption>" if rng.random()<0.2 else ""
 role=" role='presentation'" if rng.random()<0.1 else ""
 html=f"<p>before</p><table{role}>{caption}{thead}{''.join(bodyrows)}</table><p>after</p>"
 args=["--plugin-table"]
 if rng.random()<0.3: args.append("--opt-table-newline-behavior=preserve")
 if rng.random()<0.2: args.append("--opt-table-header-promotion")
 if rng.random()<0.2: args.append("--opt-table-skip-empty-rows")
 if rng.random()<0.2: args.append("--opt-table-span-cell-behavior=mirror")
 if rng.random()<0.2: args.append(f"--opt-table-cell-padding-behavior={rng.choice(['aligned','minimal','none'])}")
 if rng.random()<0.1: args.append("--opt-table-presentation-tables")
 r=run(REF,html,args); m=run(MINE,html,args)
 if r!=m:
  fails+=1; print("FAIL",i,args,repr(html),"\n ref",r,"\n mine",m)
  if fails>=15: break
print(total-fails,total,fails)
