	}''','''	type gridCell struct {
		content   string
		src       *tableCellData
		spanOf    *tableCellData
		origIndex int
	}''')
# Replace expandRows entirely
start=s.index('\texpandRows := func(ordered []*tableRowData) [][]gridCell {')
end=s.index('\tgridContents := func')
new='''	expandRows := func(ordered []*tableRowData) [][]gridCell {
		rowsCells := make([][]gridCell, len(ordered))
		for i, row := range ordered {
			for j, cell := range row.cells {
				rowsCells[i] = append(rowsCells[i], gridCell{content: cell.content, src: cell, origIndex: j})
			}
		}
		// Colspan placeholders are inserted into each row at
		// positions based on a snapshot of the row before its
		// own colspan expansion.
		for i := 0; i < len(rowsCells); i++ {
			orig := append([]gridCell(nil), rowsCells[i]...)
			for j, oc := range orig {
				if oc.src == nil || oc.spanOf != nil {
					continue
				}
				src := oc.src
				for h := 1; h < src.colspan; h++ {
					rowsCells[i] = insertCell(rowsCells[i], j+h, gridCell{content: spanContent(src), src: src, spanOf: src, origIndex: -1})
				}
			}
		}
		// Rowspan placeholders are then inserted from the last
		// row upwards, at each source cell's original index
		// within its own row.
		initialRows := len(rowsCells)
		for i := initialRows - 1; i >= 0; i-- {
			orig := append([]gridCell(nil), rowsCells[i]...)
			for _, oc := range orig {
				if oc.src == nil || oc.spanOf != nil {
					continue
				}
				src := oc.src
				for k := 1; k < src.rowspan; k++ {
					target := i + k
					for len(rowsCells) <= target {
						rowsCells = append(rowsCells, nil)
					}
					for h := 0; h < src.colspan; h++ {
						rowsCells[target] = insertCell(rowsCells[target], oc.origIndex+h, gridCell{content: spanContent(src), src: src, spanOf: src, origIndex: -1})
					}
				}
			}
		}
		return rowsCells
	}
'''
