{"command":"cat > converter_test.go <<'GO'
package main

import "testing"

func TestConvertBasic(t *testing.T) {
	tests := []struct {
		html string
		want string
	}{
		{"<p>hello <strong>world</strong></p>", "hello **world**"},
		{"<h2>Title</h2><p>body</p>", "## Title\n\nbody"},
		{"<ul><li>one</li><li>two</li></ul>", "- one\n- two"},
		{"<p>fake **bold** and real <strong>bold</strong></p>", "fake \\*\\*bold\\** and real **bold**"},
		{"<a href='/x'>link</a>", "[link](/x)"},
		{"<pre><code class='language-go'>x</code></pre>", "```go\nx\n```"},
		{"<blockquote><p>a</p><p>b</p></blockquote>", "> a\n> \n> b"},
	}
	for _, tt := range tests {
		conv := newConverter()
		got, err := conv.convert([]byte(tt.html))
		if err != nil {
			t.Fatalf("convert %q: %v", tt.html, err)
		}
		if got != tt.want {
			t.Errorf("convert %q\n got: %q\nwant: %q", tt.html, got, tt.want)
		}
	}
}

func TestConvertTable(t *testing.T) {
	conv := newConverter()
	conv.pluginTable = true
	got, err := conv.convert([]byte("<table><tr><th>A</th><th>B</th></tr><tr><td>1</td><td>2</td></tr></table>"))
	if err != nil {
		t.Fatal(err)
	}
	want := "| A | B |\n|---|---|\n| 1 | 2 |"
	if got != want {
		t.Errorf("got %q, want %q", got, want)
	}
}

func TestProcessURL(t *testing.T) {
	conv := newConverter()
	conv.domain = "https://example.com/dir/page.html"
	if got := conv.processURL("../up?q=a+b"); got != "https://example.com/up?q=a%20b" {
		t.Errorf("unexpected URL %q", got)
	}
	if got := conv.processURL("#"); got != "#" {
		t.Errorf("unexpected URL %q", got)
	}
}

func TestSelectorMatching(t *testing.T) {
	conv := newConverter()
	sel, err := ParseSelectorGroup("div > p.keep")
	if err != nil {
		t.Fatal(err)
	}
	conv.includeSelectors = []Selector{sel}
	got, err := conv.convert([]byte("<div><p class='keep'>yes</p><p>no</p></div>"))
	if err != nil {
		t.Fatal(err)
	}
	if got != "yes" {
		t.Errorf("got %q", got)
	}
	if _, err := ParseSelectorGroup(":unknown"); err == nil {
		t.Error("expected an error for an unknown pseudoclass")
	}
}
GO
GOTOOLCHAIN=local go test -mod=vendor ./... 2>&1 | tail -20"}

